css:
@property --fxp-murmur-phi {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}
.fxp-murmur {
  /* Re-theme with these four; the sun, paper, rules and tints are derived. */
  --fxp-murmur-sky: oklch(0.935 0.02 232);
  --fxp-murmur-dusk: oklch(0.86 0.075 55);
  --fxp-murmur-ink: oklch(0.255 0.018 40);
  --fxp-murmur-falcon: oklch(0.56 0.16 34);

  --fxp-murmur-sun: color-mix(in oklch, var(--fxp-murmur-dusk) 40%, oklch(0.99 0.03 92));
  --fxp-murmur-paper: color-mix(in oklch, var(--fxp-murmur-sky) 45%, oklch(0.985 0.006 80));
  --fxp-murmur-muted: color-mix(in oklch, var(--fxp-murmur-ink) 64%, var(--fxp-murmur-sky));
  --fxp-murmur-line: color-mix(in oklch, var(--fxp-murmur-ink) 13%, transparent);
  --fxp-murmur-chip: color-mix(in oklch, var(--fxp-murmur-paper) 72%, transparent);
  --fxp-murmur-out: cubic-bezier(.16, 1, .3, 1);
  --fxp-murmur-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "sky" "rules";
  grid-template-rows: minmax(0, 1fr) auto;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 288px;
  max-block-size: 380px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-murmur-paper);
  color: var(--fxp-murmur-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxp-murmur-line);

  & .fxp-murmur__sky {
    grid-area: sky;
    position: relative;
    display: grid;
    grid-template-areas: "head stats" ". ." "hint hint";
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto 1fr auto;
    column-gap: 12px;
    padding: clamp(12px, 4cqi, 18px);
    min-block-size: 0;
  }
  & .fxp-murmur__cv,
  & .fxp-murmur__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-murmur__cv { display: block; background: var(--fxp-murmur-sky); }
  & .fxp-murmur__stage {
    z-index: 1;
    cursor: none;
    touch-action: pan-y;
    outline: none;
  }
  & .fxp-murmur__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxp-murmur-falcon), inset 0 0 0 5px color-mix(in oklch, var(--fxp-murmur-falcon) 22%, transparent);
  }

  & .fxp-murmur__head,
  & .fxp-murmur__stats,
  & .fxp-murmur__hint {
    position: relative;
    z-index: 2;
    pointer-events: none;
    margin: 0;
  }
  & .fxp-murmur__head { grid-area: head; min-inline-size: 0; }
  /* a soft halo of sky keeps type legible when the flock passes behind it */
  & .fxp-murmur__head,
  & .fxp-murmur__stats {
    text-shadow: 0 0 3px var(--fxp-murmur-sky), 0 0 8px var(--fxp-murmur-sky), 0 0 14px var(--fxp-murmur-sky);
  }
  & .fxp-murmur__eyebrow {
    margin: 0 0 3px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .13em;
    text-transform: uppercase;
    color: var(--fxp-murmur-muted);
  }
  & .fxp-murmur__title {
    margin: 0;
    font-size: clamp(19px, 6.4cqi, 28px);
    font-weight: 680;
    line-height: 1.02;
    letter-spacing: -0.025em;
    text-wrap: balance;
  }

  & .fxp-murmur__stats {
    grid-area: stats;
    display: grid;
    grid-auto-flow: column;
    gap: clamp(10px, 3.4cqi, 16px);
    align-self: start;
    text-align: end;
  }
  & .fxp-murmur__stat {
    display: grid;
    gap: 2px;
    transition: opacity .5s var(--fxp-murmur-out) calc(var(--i) * 70ms + 160ms), translate .7s var(--fxp-murmur-out) calc(var(--i) * 70ms + 160ms);
    @starting-style { opacity: 0; translate: 0 -6px; }
  }
  & .fxp-murmur__stat dt {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-murmur-muted);
  }
  & .fxp-murmur__stat dd {
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
    font: 600 clamp(13px, 4cqi, 16px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
  }
  /* Φ is a registered number, so the ring eases between readings instead of snapping. */
  & .fxp-murmur__stat--phi dd {
    transition: --fxp-murmur-phi .9s var(--fxp-murmur-out);
  }
  & .fxp-murmur__stat--phi dd::before {
    content: "";
    inline-size: 13px;
    aspect-ratio: 1;
    border-radius: 50%;
    background: conic-gradient(var(--fxp-murmur-falcon) calc(var(--fxp-murmur-phi) * 1turn), color-mix(in oklch, var(--fxp-murmur-ink) 14%, transparent) 0);
    mask: radial-gradient(circle, transparent 3.4px, #000 3.9px);
  }

  & .fxp-murmur__hint {
    grid-area: hint;
    justify-self: start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 10px 5px 8px;
    border-radius: 999px;
    background: var(--fxp-murmur-chip);
    box-shadow: 0 0 0 1px var(--fxp-murmur-line);
    font-size: 11px;
    font-weight: 550;
    color: var(--fxp-murmur-ink);
    transition: opacity .45s var(--fxp-murmur-out), translate .6s var(--fxp-murmur-out), filter .45s var(--fxp-murmur-out);
  }
  & .fxp-murmur__hint svg {
    inline-size: 13px;
    block-size: 13px;
    fill: var(--fxp-murmur-falcon);
    stroke: var(--fxp-murmur-falcon);
    stroke-width: 1.5;
    stroke-linejoin: round;
  }
  &[data-used] .fxp-murmur__hint,
  &:has(.fxp-murmur__stage:focus-visible) .fxp-murmur__hint {
    opacity: 0;
    translate: 0 6px;
    filter: blur(3px);
  }

  & .fxp-murmur__rules {
    grid-area: rules;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-template-rows: auto auto;
    column-gap: clamp(10px, 4cqi, 20px);
    row-gap: 4px;
    padding: 10px clamp(12px, 4cqi, 18px) 12px;
    border-top: 1px solid var(--fxp-murmur-line);
    background: var(--fxp-murmur-paper);
  }
  /* Each rule spans both rows and adopts them, so names and sliders line up across columns. */
  & .fxp-murmur__rule {
    grid-row: span 2;
    display: grid;
    grid-template-rows: subgrid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "name out" "range range";
    column-gap: 4px;
    align-items: center;
    min-inline-size: 0;
    transition: opacity .5s var(--fxp-murmur-out) calc(var(--i) * 60ms + 240ms), translate .7s var(--fxp-murmur-out) calc(var(--i) * 60ms + 240ms);
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxp-murmur__name {
    grid-area: name;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: -0.005em;
    color: var(--fxp-murmur-muted);
    transition: color .25s var(--fxp-murmur-out);
  }
  & .fxp-murmur__rule output {
    grid-area: out;
    font: 600 11px ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxp-murmur-ink);
  }
  & .fxp-murmur__rule input {
    grid-area: range;
    inline-size: 100%;
    margin: 0;
    block-size: 18px;
    accent-color: var(--fxp-murmur-falcon);
    cursor: pointer;
  }
  & .fxp-murmur__rule:has(input:focus-visible) .fxp-murmur__name,
  & .fxp-murmur__rule:hover .fxp-murmur__name { color: var(--fxp-murmur-falcon); }
  & .fxp-murmur__rule input:focus-visible {
    outline: 2px solid var(--fxp-murmur-falcon);
    outline-offset: 2px;
    border-radius: 4px;
  }
  & .fxp-murmur__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 340px) {
  .fxp-murmur {
    & .fxp-murmur__eyebrow { letter-spacing: .08em; }
    & .fxp-murmur__name { font-size: 10.5px; }
    & .fxp-murmur__rule output { font-size: 10px; }
    & .fxp-murmur__rules { column-gap: 9px; }
    & .fxp-murmur__stats { gap: 10px; }
  }
}
@container (min-width: 560px) {
  .fxp-murmur {
    & .fxp-murmur__rules { padding-block: 12px 14px; }
    & .fxp-murmur__name { font-size: 12px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxp-murmur {
    & .fxp-murmur__stat,
    & .fxp-murmur__rule,
    & .fxp-murmur__hint,
    & .fxp-murmur__stat--phi dd { transition: none; }
    & .fxp-murmur__stage { cursor: default; }
  }
}

js:
/* Murmuration — Reynolds boids with topological neighbours.
   Each bird steers by its K nearest flockmates (not everything within a radius),
   which is what field studies of starlings measured and what keeps a flock
   coherent while its density changes. Neighbours come from a uniform grid
   rebuilt each step; alarm hops bird to bird so the falcon starts a wave. */
const sky = root.querySelector('.fxp-murmur__sky');
const cv = root.querySelector('.fxp-murmur__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-murmur__stage');
const probe = root.querySelector('.fxp-murmur__probe');
const outN = root.querySelector('[data-k="n"]');
const outPhi = root.querySelector('[data-k="phi"]');
const live = root.querySelector('.fxp-murmur__sr');
const sliders = [...root.querySelectorAll('.fxp-murmur__rule input')];
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2;
const K = 7;            // topological neighbours
const R = 30;           // neighbour search radius and grid cell, px
const RS = 8;           // personal space, px
const weights = { sep: 1, ali: 1.3, coh: .8 };

let W = 0, H = 0, DPR = 1, N = 0, HZ = 0, V0 = 70;
let px, py, vx, vy, nvx, nvy, dep, flap, rate, alarm, alarm2;
let cols = 0, rows = 0, head = null, next = null;
const nbI = new Int32Array(K), nbD = new Float32Array(K);
const bg = document.createElement('canvas');
const bgx = bg.getContext('2d');
const pal = {};
const hawk = { x: 0, y: 0, tx: 0, ty: 0, hx: 1, hy: 0, on: 0, want: 0, stoop: 0 };
let t = 0, phiClock = 0, shownN = -1, raf = 0, last = 0, seen = true, dead = false;

/* ── colour: resolve any CSS colour (oklch, color-mix, var chains) to sRGB bytes ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}

function theme() {
  pal.sky = rgb('--fxp-murmur-sky');
  pal.dusk = rgb('--fxp-murmur-dusk');
  pal.sun = rgb('--fxp-murmur-sun');
  pal.ink = rgb('--fxp-murmur-ink');
  pal.hawk = rgb('--fxp-murmur-falcon');
  paintBg();
}

/* Sky, low sun, a far treeline and the reedbed, painted once per size/theme. */
function paintBg() {
  if (!W || !pal.sky) return;
  bg.width = cv.width; bg.height = cv.height;
  const g = bgx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const lg = g.createLinearGradient(0, 0, 0, HZ);
  lg.addColorStop(0, css(pal.sky, 1));
  lg.addColorStop(.6, css(mix(pal.sky, pal.dusk, .5), 1));
  lg.addColorStop(1, css(pal.dusk, 1));
  g.fillStyle = lg;
  g.fillRect(0, 0, W, H);
  const sx = W * .7, sy = HZ + 2, sr = Math.max(W, H) * .62;
  const rg = g.createRadialGradient(sx, sy, 0, sx, sy, sr);
  rg.addColorStop(0, css(pal.sun, 1));
  rg.addColorStop(.18, css(pal.sun, .55));
  rg.addColorStop(1, css(pal.sun, 0));
  g.fillStyle = rg;
  g.fillRect(0, 0, W, H);
  const r = rng(11);
  g.fillStyle = css(mix(pal.dusk, pal.ink, .34), 1);
  g.beginPath();
  g.moveTo(0, H);
  for (let x = 0; x <= W + 4; x += 4) {
    const crown = Math.max(0, Math.sin(x * .019) * 7 + Math.sin(x * .061 + 2) * 3.4);
    g.lineTo(x, HZ - 1 - crown - r() * 1.6);
  }
  g.lineTo(W, H);
  g.closePath();
  g.fill();
  g.fillStyle = css(pal.ink, 1);
  g.fillRect(0, HZ + 5, W, H);
  g.strokeStyle = css(pal.ink, .92);
  g.lineWidth = .9;
  g.lineCap = 'round';
  g.beginPath();
  const heads = [];
  for (let x = -2; x < W + 2; x += 1.6) {
    const clump = .55 + .45 * Math.sin(x * .045) * Math.sin(x * .013 + 1);
    const hgt = 5 + r() * 13 * clump + 4 * clump;
    const lean = (r() - .5) * 3.4 + 1.1;
    g.moveTo(x, HZ + 7);
    g.quadraticCurveTo(x + lean * .3, HZ + 7 - hgt * .6, x + lean, HZ + 7 - hgt);
    if (r() < .22) heads.push([x + lean, HZ + 7 - hgt, lean]);
  }
  g.stroke();
  g.fillStyle = css(pal.ink, 1);
  g.beginPath();
  for (const [x, y, l] of heads) {
    g.moveTo(x, y);
    g.ellipse(x + l * .2, y - 2.2, 1.25, 3.2, l * .12, 0, TAU);
  }
  g.fill();
}

/* ── flock state ── */
function seed() {
  N = Math.max(300, Math.min(1100, Math.round(W * HZ / 105)));
  px = new Float32Array(N); py = new Float32Array(N);
  vx = new Float32Array(N); vy = new Float32Array(N);
  nvx = new Float32Array(N); nvy = new Float32Array(N);
  dep = new Float32Array(N); flap = new Float32Array(N); rate = new Float32Array(N);
  alarm = new Float32Array(N); alarm2 = new Float32Array(N);
  next = new Int32Array(N);
  const cx = W * .42, cy = HZ * .44, rx = W * .27, ry = HZ * .16, hd = -.28;
  for (let i = 0; i < N; i++) {
    const a = Math.random() * TAU, rr = Math.sqrt(Math.random());
    const bend = Math.sin(a * 2) * .35;
    px[i] = cx + Math.cos(a) * rr * rx;
    py[i] = cy + Math.sin(a) * rr * ry + bend * ry * rr;
    const h = hd + (Math.random() - .5) * .5, s = V0 * (.9 + Math.random() * .2);
    vx[i] = Math.cos(h) * s; vy[i] = Math.sin(h) * s;
    dep[i] = .62 + Math.random() * .62;
    flap[i] = Math.random() * TAU;
    rate[i] = 10 + Math.random() * 8;
  }
  grid();
}
function grid() {
  cols = Math.ceil(W / R) + 3; rows = Math.ceil(H / R) + 3;
  head = new Int32Array(cols * rows);
}
function cellOf(x, y) {
  let c = Math.floor(x / R) + 1, r = Math.floor(y / R) + 1;
  c = c < 0 ? 0 : c >= cols ? cols - 1 : c;
  r = r < 0 ? 0 : r >= rows ? rows - 1 : r;
  return r * cols + c;
}
function bin() {
  head.fill(-1);
  for (let i = 0; i < N; i++) {
    const k = cellOf(px[i], py[i]);
    next[i] = head[k]; head[k] = i;
  }
}

function step(dt) {
  bin();
  t += dt;
  const ws = weights.sep, wa = weights.ali, wc = weights.coh;
  /* the roost: a drifting ellipse the flock is held inside, loosely */
  const rx0 = W * (.5 + .16 * Math.sin(t * .23)), ry0 = HZ * (.55 + .07 * Math.sin(t * .31 + 1.3));
  const ex0 = W * .22, ey0 = HZ * .15;
  const decay = Math.exp(-dt * 1.5);
  const hawkR = 58 + hawk.stoop * 70, hawkOn = hawk.on;
  const R2 = R * R, m = 40, mTop = Math.min(78, HZ * .3), floor = HZ - 44;
  for (let i = 0; i < N; i++) {
    const x = px[i], y = py[i];
    let cnt = 0;
    const c0 = Math.floor(x / R) + 1, r0 = Math.floor(y / R) + 1;
    for (let dr = -1; dr <= 1; dr++) {
      const rr = r0 + dr;
      if (rr < 0 || rr >= rows) continue;
      for (let dc = -1; dc <= 1; dc++) {
        const cc = c0 + dc;
        if (cc < 0 || cc >= cols) continue;
        for (let j = head[rr * cols + cc]; j !== -1; j = next[j]) {
          if (j === i) continue;
          const dx = px[j] - x, dy = py[j] - y, d2 = dx * dx + dy * dy;
          if (d2 > R2) continue;
          let s;
          if (cnt < K) s = cnt++;
          else if (d2 < nbD[K - 1]) s = K - 1;
          else continue;
          while (s > 0 && nbD[s - 1] > d2) { nbD[s] = nbD[s - 1]; nbI[s] = nbI[s - 1]; s--; }
          nbD[s] = d2; nbI[s] = j;
        }
      }
    }
    let ax = 0, ay = 0, al = alarm[i] * decay;
    if (cnt) {
      let sx = 0, sy = 0, avx = 0, avy = 0, cx = 0, cy = 0, hot = 0;
      for (let q = 0; q < cnt; q++) {
        const j = nbI[q], d = Math.sqrt(nbD[q]) + 1e-3;
        if (d < RS) {
          const f = (1 - d / RS) / d;
          sx -= (px[j] - x) * f; sy -= (py[j] - y) * f;
        }
        avx += vx[j]; avy += vy[j]; cx += px[j]; cy += py[j];
        if (alarm[j] > hot) hot = alarm[j];
      }
      avx /= cnt; avy /= cnt; cx = cx / cnt - x; cy = cy / cnt - y;
      ax += sx * 300 * ws + (avx - vx[i]) * 2.2 * wa + cx * 1.5 * wc;
      ay += sy * 300 * ws + (avy - vy[i]) * 2.2 * wa + cy * 1.5 * wc;
      if (hot * .84 > al) al = hot * .84;           /* panic spreads one hop per step */
    }
    const ex = rx0 - x, ey = ry0 - y, el = Math.hypot(ex, ey) + 1;
    const out = Math.hypot(ex / ex0, ey / ey0);            /* > 1 outside the roost ellipse */
    const pull = 8 + (out > 1 ? (out - 1) * 120 : 0);
    ax += ex / el * pull; ay += ey / el * pull;
    if (x < m) ax += (m - x) * 9; else if (x > W - m) ax -= (x - W + m) * 9;
    if (y < mTop) ay += (mTop - y) * 9; else if (y > floor) ay -= (y - floor) * 11;
    if (hawkOn > .01) {
      const fx = x - hawk.x, fy = y - hawk.y, fd2 = fx * fx + fy * fy;
      if (fd2 < hawkR * hawkR) {
        const fd = Math.sqrt(fd2) + 1e-3, k = 1 - fd / hawkR;
        ax += fx / fd * 1700 * k * k * hawkOn;
        ay += fy / fd * 1700 * k * k * hawkOn;
        if (k * 1.3 > al) al = Math.min(1, k * 1.3);
      }
    }
    alarm2[i] = al;
    let nx = vx[i] + ax * dt, ny = vy[i] + ay * dt;
    const sp = Math.hypot(nx, ny) + 1e-6;
    const lo = V0 * .62, hi = V0 * (1.5 + al * .7);
    if (sp > hi) { nx *= hi / sp; ny *= hi / sp; } else if (sp < lo) { nx *= lo / sp; ny *= lo / sp; }
    nvx[i] = nx; nvy[i] = ny;
  }
  for (let i = 0; i < N; i++) {
    vx[i] = nvx[i]; vy[i] = nvy[i];
    px[i] += vx[i] * dt; py[i] += vy[i] * dt;
    flap[i] += rate[i] * dt * (1 + alarm2[i] * 1.4);
  }
  const sw2 = alarm; alarm = alarm2; alarm2 = sw2;
}

/* Polarisation Φ = |Σ v̂| / N: 1 when every bird flies the same heading. */
function order() {
  let sx = 0, sy = 0;
  for (let i = 0; i < N; i++) {
    const s = Math.hypot(vx[i], vy[i]) + 1e-6;
    sx += vx[i] / s; sy += vy[i] / s;
  }
  return Math.hypot(sx, sy) / Math.max(1, N);
}
function readout() {
  if (N !== shownN) { shownN = N; outN.textContent = N.toLocaleString('en-US'); }
  const phi = order();
  outPhi.textContent = phi.toFixed(2);
  outPhi.style.setProperty('--fxp-murmur-phi', phi.toFixed(3));
}

function draw() {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.drawImage(bg, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (let pass = 0; pass < 2; pass++) {
    const near = pass === 1;
    ctx.beginPath();
    for (let i = 0; i < N; i++) {
      if ((dep[i] > .95) !== near) continue;
      const s = dep[i], sp = Math.hypot(vx[i], vy[i]) + 1e-6, ux = vx[i] / sp, uy = vy[i] / sp;
      const L = 1.9 * s;
      ctx.moveTo(px[i] - ux * L, py[i] - uy * L);
      ctx.lineTo(px[i] + ux * L * .85, py[i] + uy * L * .85);
    }
    ctx.lineWidth = near ? 1.55 : 1.05;
    ctx.strokeStyle = css(pal.ink, near ? .9 : .52);
    ctx.stroke();
    ctx.beginPath();
    for (let i = 0; i < N; i++) {
      if ((dep[i] > .95) !== near) continue;
      const s = dep[i], sp = Math.hypot(vx[i], vy[i]) + 1e-6, ux = vx[i] / sp, uy = vy[i] / sp;
      /* banking birds show more wing: alarm widens the span, which reads as a dark wave */
      const span = s * (1.1 + 1.3 * Math.abs(Math.sin(flap[i]))) * (1 + alarm[i] * 1.4);
      const back = s * 1.55;
      ctx.moveTo(px[i] - uy * span - ux * back, py[i] + ux * span - uy * back);
      ctx.lineTo(px[i], py[i]);
      ctx.lineTo(px[i] + uy * span - ux * back, py[i] - ux * span - uy * back);
    }
    ctx.lineWidth = near ? 1.15 : .8;
    ctx.stroke();
  }
  if (hawk.on > .01) {
    ctx.save();
    ctx.translate(hawk.x, hawk.y);
    if (hawk.stoop > .02) {
      ctx.beginPath();
      ctx.arc(0, 0, (58 + hawk.stoop * 70) * (1.15 - hawk.stoop * .15), 0, TAU);
      ctx.strokeStyle = css(pal.hawk, .35 * hawk.stoop * hawk.on);
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    ctx.rotate(Math.atan2(hawk.hy, hawk.hx));
    const s = 1 + hawk.stoop * .25;
    ctx.scale(s, s);
    ctx.globalAlpha = hawk.on;
    ctx.fillStyle = css(pal.hawk, 1);
    ctx.beginPath();
    ctx.moveTo(8, 0);
    ctx.lineTo(1, -1.6);
    ctx.lineTo(-3, -10 + hawk.stoop * 5);
    ctx.lineTo(-2.2, -1.4);
    ctx.lineTo(-8, -2.4);
    ctx.lineTo(-6.5, 0);
    ctx.lineTo(-8, 2.4);
    ctx.lineTo(-2.2, 1.4);
    ctx.lineTo(-3, 10 - hawk.stoop * 5);
    ctx.lineTo(1, 1.6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
}

/* ── host: DPR canvas, resize, visibility, teardown ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W, ow = W, oh = H;
  W = w; H = h; HZ = H * .86;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  V0 = Math.max(55, Math.min(95, Math.min(W, H) * .25));
  if (first) {
    seed();
    if (calm) settle(150);
  } else {
    for (let i = 0; i < N; i++) { px[i] *= W / ow; py[i] *= H / oh; }
    grid();
  }
  paintBg();
  readout();
  draw();
}
function settle(n) { for (let k = 0; k < n; k++) step(1 / 30); }
function kick() {
  if (dead || raf || calm || !seen || document.hidden || !N) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 1 / 24) : 1 / 60;
  last = now;
  const kx = 1 - Math.exp(-dt * 9);
  hawk.on += (hawk.want - hawk.on) * (1 - Math.exp(-dt * 6));
  const ox = hawk.x, oy = hawk.y;
  hawk.x += (hawk.tx - hawk.x) * kx; hawk.y += (hawk.ty - hawk.y) * kx;
  const mvx = hawk.x - ox, mvy = hawk.y - oy, ml = Math.hypot(mvx, mvy);
  if (ml > .3) { hawk.hx += (mvx / ml - hawk.hx) * .25; hawk.hy += (mvy / ml - hawk.hy) * .25; }
  hawk.stoop *= Math.exp(-dt * 2.2);
  step(dt);
  phiClock += dt;
  if (phiClock > .3) { phiClock = 0; readout(); }
  draw();
  raf = requestAnimationFrame(frame);
}
const ro = new ResizeObserver(([e]) => { size(e.contentRect.width, e.contentRect.height); kick(); });
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => {
  calm = mq.matches;
  hawk.want = 0; hawk.on = 0;
  if (calm) { settle(60); readout(); draw(); }
  kick();
};
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); draw(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
/* The library unmounts by clearing innerHTML, often while we are paused off screen. */
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── the falcon: pointer, touch and keyboard ── */
function local(e) {
  const r = cv.getBoundingClientRect();
  return [e.clientX - r.left, e.clientY - r.top];
}
function used() { if (!('used' in root.dataset)) root.dataset.used = ''; }
stage.addEventListener('pointermove', (e) => {
  if (calm) return;
  const [x, y] = local(e);
  if (hawk.want === 0) { hawk.x = x; hawk.y = y; }
  hawk.tx = x; hawk.ty = y; hawk.want = 1;
  used();
});
stage.addEventListener('pointerdown', (e) => {
  const [x, y] = local(e);
  if (calm) { stoopStill(x, y); used(); return; }
  hawk.tx = x; hawk.ty = y; hawk.want = 1; hawk.stoop = 1;
  if (e.pointerType !== 'mouse') { hawk.x = x; hawk.y = y; }
  used();
});
stage.addEventListener('pointerleave', (e) => { if (e.pointerType === 'mouse') hawk.want = 0; });
stage.addEventListener('pointerup', (e) => { if (e.pointerType !== 'mouse') hawk.want = 0; });
stage.addEventListener('pointercancel', () => { hawk.want = 0; });
stage.addEventListener('focus', () => {
  if (calm || hawk.want) return;
  hawk.x = hawk.tx = W * .5; hawk.y = hawk.ty = HZ * .5;
});
stage.addEventListener('blur', () => { hawk.want = 0; });
const DIRS = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };
stage.addEventListener('keydown', (e) => {
  const d = DIRS[e.key];
  if (d) {
    if (calm) return;
    const s = e.shiftKey ? 48 : 16;
    hawk.tx = Math.max(8, Math.min(W - 8, hawk.tx + d[0] * s));
    hawk.ty = Math.max(8, Math.min(HZ - 8, hawk.ty + d[1] * s));
    hawk.want = 1;
  } else if (e.key === 'Enter' || e.key === ' ') {
    if (calm) { stoopStill(W * .5, HZ * .5); return; }
    hawk.want = 1; hawk.stoop = 1;
    live.textContent = 'Falcon stoops; the flock splits around it.';
  } else if (e.key === 'Escape') {
    hawk.want = 0;
    live.textContent = 'Falcon gone. The flock closes up.';
  } else return;
  e.preventDefault();
  used();
});

/* Reduced motion: a tap is a single stoop, settled offline and shown as a still. */
function stoopStill(x, y) {
  hawk.x = hawk.tx = x; hawk.y = hawk.ty = y; hawk.on = 1; hawk.stoop = 1;
  for (let k = 0; k < 24; k++) { step(1 / 30); hawk.stoop *= .9; }
  readout();
  draw();
  hawk.on = 0; hawk.stoop = 0;
  live.textContent = 'Falcon stoops; the flock splits around it.';
}

/* ── the three rules ── */
sliders.forEach((s) => {
  const out = s.parentElement.querySelector('output');
  const apply = () => {
    const v = +s.value / 50;
    weights[s.dataset.rule] = v;
    out.textContent = v.toFixed(2);
  };
  s.addEventListener('input', () => {
    apply();
    if (calm) { settle(45); readout(); draw(); }
  });
  apply();
});

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxp-galaxy {
  /* Re-theme with these four. */
  --fxp-galaxy-void: oklch(0.145 0.008 275);
  --fxp-galaxy-core: oklch(0.9 0.075 80);
  --fxp-galaxy-young: oklch(0.87 0.045 238);
  --fxp-galaxy-knot: oklch(0.7 0.165 18);

  --fxp-galaxy-text: color-mix(in oklch, var(--fxp-galaxy-core) 30%, oklch(0.98 0 0));
  --fxp-galaxy-muted: color-mix(in oklch, var(--fxp-galaxy-text) 56%, var(--fxp-galaxy-void));
  --fxp-galaxy-line: color-mix(in oklch, var(--fxp-galaxy-text) 14%, transparent);
  --fxp-galaxy-well: color-mix(in oklch, var(--fxp-galaxy-void) 70%, transparent);
  --fxp-galaxy-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head meta" ". ." "types hint";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 280px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-galaxy-void);
  color: var(--fxp-galaxy-text);
  font-family: system-ui, sans-serif;

  & .fxp-galaxy__cv,
  & .fxp-galaxy__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-galaxy__cv { display: block; }
  & .fxp-galaxy__stage {
    z-index: 1;
    cursor: grab;
    touch-action: pan-y;
    outline: none;
    border-radius: inherit;
  }
  & .fxp-galaxy__stage:active { cursor: grabbing; }
  & .fxp-galaxy__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxp-galaxy-core), inset 0 0 0 5px color-mix(in oklch, var(--fxp-galaxy-core) 20%, transparent);
  }

  & .fxp-galaxy__head,
  & .fxp-galaxy__meta,
  & .fxp-galaxy__hint {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
  }
  & .fxp-galaxy__head { grid-area: head; min-inline-size: 0; }
  & .fxp-galaxy__eyebrow {
    margin: 0 0 3px;
    font: 500 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--fxp-galaxy-muted);
  }
  & .fxp-galaxy__title {
    margin: 0;
    font-size: clamp(19px, 6.4cqi, 28px);
    font-weight: 300;
    line-height: 1.02;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  & .fxp-galaxy__caption {
    margin: 6px 0 0;
    max-inline-size: 24ch;
    font-size: 11px;
    line-height: 1.35;
    color: var(--fxp-galaxy-muted);
    text-wrap: pretty;
  }

  & .fxp-galaxy__meta {
    grid-area: meta;
    display: grid;
    gap: 6px;
    align-self: start;
    text-align: end;
  }
  & .fxp-galaxy__meta div {
    display: flex;
    justify-content: flex-end;
    align-items: baseline;
    gap: 8px;
    transition: opacity .6s var(--fxp-galaxy-out) calc(var(--i) * 80ms + 200ms), translate .8s var(--fxp-galaxy-out) calc(var(--i) * 80ms + 200ms);
    @starting-style { opacity: 0; translate: 8px 0; }
  }
  & .fxp-galaxy__meta dt {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-galaxy-muted);
  }
  & .fxp-galaxy__meta dd {
    margin: 0;
    min-inline-size: 4.5ch;
    font: 500 12.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxp-galaxy__types {
    grid-area: types;
    position: relative;
    z-index: 2;
    justify-self: start;
    align-self: end;
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(40px, auto);
    padding: 3px;
    border-radius: 999px;
    background: var(--fxp-galaxy-well);
    box-shadow: inset 0 0 0 1px var(--fxp-galaxy-line);
    backdrop-filter: blur(6px);
  }
  & .fxp-galaxy__thumb {
    position: absolute;
    inset-block: 3px;
    inset-inline-start: 0;
    border-radius: 999px;
    background: var(--fxp-galaxy-core);
    box-shadow: 0 0 18px color-mix(in oklch, var(--fxp-galaxy-core) 45%, transparent);
    pointer-events: none;
  }
  & .fxp-galaxy__type {
    position: relative;
    padding: 6px 11px;
    border: 0;
    border-radius: 999px;
    background: none;
    color: var(--fxp-galaxy-muted);
    font: 600 11.5px/1 system-ui, sans-serif;
    letter-spacing: .02em;
    cursor: pointer;
    transition: color .3s var(--fxp-galaxy-out), scale .35s var(--fxp-galaxy-out);
  }
  & .fxp-galaxy__type:hover { color: var(--fxp-galaxy-text); }
  & .fxp-galaxy__type:active { scale: .94; }
  & .fxp-galaxy__type[aria-checked="true"] { color: var(--fxp-galaxy-void); }
  & .fxp-galaxy__type:focus-visible {
    outline: 2px solid var(--fxp-galaxy-core);
    outline-offset: 2px;
  }

  & .fxp-galaxy__hint {
    grid-area: hint;
    align-self: end;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding-block-end: 6px;
    font-size: 11px;
    color: var(--fxp-galaxy-muted);
    transition: opacity .5s var(--fxp-galaxy-out), translate .6s var(--fxp-galaxy-out);
  }
  & .fxp-galaxy__hint svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.3;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  &[data-used] .fxp-galaxy__hint { opacity: 0; translate: 0 4px; }
}

@container (max-width: 330px) {
  .fxp-galaxy {
    & .fxp-galaxy__hint { display: none; }
    & .fxp-galaxy__type { padding-inline: 9px; }
    & .fxp-galaxy__caption { max-inline-size: 19ch; }
  }
}
@container (min-width: 540px) {
  .fxp-galaxy {
    & .fxp-galaxy__caption { font-size: 12px; max-inline-size: 30ch; }
    & .fxp-galaxy__meta dd { font-size: 14px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxp-galaxy {
    & .fxp-galaxy__meta div,
    & .fxp-galaxy__type,
    & .fxp-galaxy__hint { transition: none; }
  }
}

js:
/* Density wave — a Kalnajs spiral.
   No arm is ever drawn. Every star rides a centred ellipse whose orientation
   θ(a) advances with its size a; where neighbouring ellipses crowd together the
   disc is denser, and that crowding traces two trailing arms, 45° behind each
   ellipse's major axis. Old stars orbit freely along their ellipses; young
   stars, HII knots and dust lanes are pinned to the crowded phase. */
const cv = root.querySelector('.fxp-galaxy__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-galaxy__stage');
const probe = root.querySelector('.fxp-galaxy__probe');
const outInc = root.querySelector('[data-k="inc"]');
const outPa = root.querySelector('[data-k="pa"]');
const outN = root.querySelector('[data-k="n"]');
const caption = root.querySelector('.fxp-galaxy__caption');
const group = root.querySelector('.fxp-galaxy__types');
const thumb = root.querySelector('.fxp-galaxy__thumb');
const btns = [...root.querySelectorAll('.fxp-galaxy__type')];
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, DEG = Math.PI / 180;
/* twist: radians of ellipse rotation per unit radius · ecc: 1 − b/a · bR: bulge scale */
const TYPES = [
  { twist: 6.4, ecc: .27, bR: .17, bulge: 1.5, young: .55, bar: 0, cap: 'Sa · tightly wound arms around a large, bright bulge' },
  { twist: 4.5, ecc: .31, bR: .12, bulge: 1, young: 1, bar: 0, cap: 'Sb · moderately wound arms' },
  { twist: 2.8, ecc: .35, bR: .075, bulge: .5, young: 1.45, bar: 0, cap: 'Sc · open arms, a small bulge and bright star-forming knots' },
  { twist: 4.4, ecc: .33, bR: .075, bulge: .6, young: 1.1, bar: .32, cap: 'SBb · a stellar bar through the core feeds the arms' },
];
let cur = 1;
const P = Object.assign({}, TYPES[cur]);
const KEYS = ['twist', 'ecc', 'bR', 'bulge', 'young', 'bar'];

let W = 0, H = 0, DPR = 1, N = 0, cx = 0, cy = 0, Rpx = 100;
let S, PH, Z, CLS, LV, J;             /* per star: radius seed, phase, height, class, level, jitter */
let bins = [];
let KN = 0, kA, kS, kJ, kR, kT;       /* HII knots */
let DN = 0, dA, dS, dJ, dR;           /* dust */
const view = { inc: 42, pa: 24, incT: 42, paT: 24, vInc: 0, vPa: 0, drag: null };
let t = 0, raf = 0, last = 0, seen = true, dead = false, shown = '';
const pal = {};
const bg = document.createElement('canvas'), bgx = bg.getContext('2d');
const knot = document.createElement('canvas'), dust = document.createElement('canvas');

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
function gauss() {
  let u = 0, v = 0;
  while (!u) u = Math.random();
  while (!v) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(TAU * v);
}
function sprite(c, col, size, soft) {
  c.width = c.height = size;
  const g = c.getContext('2d'), r = size / 2;
  const gr = g.createRadialGradient(r, r, 0, r, r, r);
  gr.addColorStop(0, css(col, 1));
  gr.addColorStop(soft, css(col, .35));
  gr.addColorStop(1, css(col, 0));
  g.fillStyle = gr;
  g.fillRect(0, 0, size, size);
}
function theme() {
  pal.void = rgb('--fxp-galaxy-void');
  pal.core = rgb('--fxp-galaxy-core');
  pal.young = rgb('--fxp-galaxy-young');
  pal.knot = rgb('--fxp-galaxy-knot');
  pal.disk = mix(pal.core, pal.young, .45);
  pal.dust = mix(pal.void, pal.knot, .12);
  sprite(knot, pal.knot, 32, .3);
  sprite(dust, pal.dust, 32, .5);
  paintBg();
}
function paintBg() {
  if (!W || !pal.void) return;
  bg.width = cv.width; bg.height = cv.height;
  bgx.setTransform(DPR, 0, 0, DPR, 0, 0);
  bgx.fillStyle = css(pal.void, 1);
  bgx.fillRect(0, 0, W, H);
  let s = 90210;
  const r = () => ((s = Math.imul(s ^ (s >>> 13), 0x5bd1e995) + 0x3c6ef372 | 0) >>> 0) / 4294967296;
  const n = Math.round(W * H / 700);
  for (let i = 0; i < n; i++) {
    const b = r();
    bgx.fillStyle = css(b > .9 ? pal.young : pal.core, .1 + b * b * .55);
    const z = b > .97 ? 1.4 : .9;
    bgx.fillRect(r() * W, r() * H, z, z);
  }
  const v = bgx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * .3, W / 2, H / 2, Math.hypot(W, H) * .6);
  v.addColorStop(0, css(pal.void, 0));
  v.addColorStop(1, css(pal.void, .7));
  bgx.fillStyle = v;
  bgx.fillRect(0, 0, W, H);
}

function seed() {
  N = Math.max(3500, Math.min(10000, Math.round(W * H / 15)));
  S = new Float32Array(N); PH = new Float32Array(N); Z = new Float32Array(N);
  CLS = new Uint8Array(N); LV = new Uint8Array(N); J = new Float32Array(N);
  const E = 1 - Math.exp(-1 / .3);
  bins = Array.from({ length: 9 }, () => []);
  for (let i = 0; i < N; i++) {
    const u = Math.random();
    const c = u < .24 ? 0 : u < .66 ? 1 : 2;           /* bulge · old disc · young */
    CLS[i] = c;
    if (c === 0) S[i] = Math.abs(gauss()) + .05;
    else if (c === 1) S[i] = Math.min(1.08, -.3 * Math.log(1 - Math.random() * E) + .03);
    else S[i] = .13 + Math.sqrt(Math.random()) * .85;
    PH[i] = Math.random() * TAU;
    Z[i] = gauss() * (c === 0 ? .7 : c === 1 ? .03 : .014);
    J[i] = gauss();
    const l = Math.random();
    LV[i] = l < .62 ? 0 : l < .93 ? 1 : 2;
    bins[c * 3 + LV[i]].push(i);
  }
  bins = bins.map((b) => Int32Array.from(b));
  KN = Math.round(N / 85);
  kA = new Float32Array(KN); kS = new Uint8Array(KN); kJ = new Float32Array(KN); kR = new Float32Array(KN); kT = new Float32Array(KN);
  for (let i = 0; i < KN; i++) {
    kA[i] = .2 + Math.sqrt(Math.random()) * .74; kS[i] = Math.random() < .5 ? 0 : 1;
    kJ[i] = gauss(); kR[i] = 1.2 + Math.pow(Math.random(), 3) * 5; kT[i] = Math.random() * TAU;
  }
  DN = Math.round(N / 9);
  dA = new Float32Array(DN); dS = new Uint8Array(DN); dJ = new Float32Array(DN); dR = new Float32Array(DN);
  for (let i = 0; i < DN; i++) {
    dA[i] = .1 + Math.sqrt(Math.random()) * .85; dS[i] = Math.random() < .5 ? 0 : 1;
    dJ[i] = gauss(); dR[i] = 2.5 + Math.random() * 4.5;
