}

/* ── projection: orbit ellipse → disc → inclined disc → sky ── */
let ci = 1, si = 0, cpa = 1, spa = 0, OMp = 0;
let X = 0, Y = 0;
const smooth = (a, b, x) => { const k = Math.min(1, Math.max(0, (x - a) / (b - a))); return k * k * (3 - 2 * k); };
