}
function theta(a) { return P.twist * Math.max(0, a - P.bar) - OMp; }
/* ellipse parameter at which the orbit crosses the arm (polar angle θ − π/4) */
function lock(e) { return Math.atan2(-1, 1 - e); }
function place(a, e, th, ph, z) {
