  g.addColorStop(.45, css(pal.disk, .06));
  g.addColorStop(1, css(pal.disk, 0));
  ctx.fillStyle = g;
  ctx.fillRect(-Rpx, -Rpx, Rpx * 2, Rpx * 2);
  ctx.restore();
  const gr = Rpx * (P.bR * 2.4 + .05);
