  ctx.globalAlpha = .3;
  for (let i = 0; i < DN; i++) {
    const a = dA[i], e = ecc(a);
    place(a, e, theta(a), lock(e) + dS[i] * Math.PI + .2 + dJ[i] * .09, 0);
