}

function readout() {
  const inc = Math.round(view.inc), pa = Math.round(((view.pa % 180) + 180) % 180);
  const key = inc + '/' + pa;
  if (key === shown) return;
  shown = key;
  outInc.textContent = inc + '°';
  outPa.textContent = pa + '°';
}

/* ── type changes: parameters ease, so arms visibly rewind ── */
const SPRING = 'linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1)';
let thumbAt = null;
function placeThumb(animate) {
