/* ── host ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  cx = W * .5; cy = H * .53;
  Rpx = Math.min(W * .43, H * .47);
