css:
.fxp-filings {
  /* Re-theme with these four. */
  --fxp-filings-paper: oklch(0.962 0.014 88);
  --fxp-filings-iron: oklch(0.29 0.012 255);
  --fxp-filings-north: oklch(0.57 0.18 27);
  --fxp-filings-south: oklch(0.58 0.035 245);

  --fxp-filings-grid: color-mix(in oklch, var(--fxp-filings-south) 24%, var(--fxp-filings-paper));
  --fxp-filings-muted: color-mix(in oklch, var(--fxp-filings-iron) 62%, var(--fxp-filings-paper));
  --fxp-filings-line: color-mix(in oklch, var(--fxp-filings-iron) 13%, transparent);
  --fxp-filings-chip: color-mix(in oklch, var(--fxp-filings-paper) 86%, transparent);
  --fxp-filings-len: clamp(64px, 21cqi, 104px);
  --fxp-filings-out: cubic-bezier(.16, 1, .3, 1);
  --fxp-filings-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "tools hint";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 288px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-filings-paper);
  color: var(--fxp-filings-iron);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxp-filings-line);

  & .fxp-filings__sheet {
    position: absolute;
    inset: 0;
    z-index: 0;
  }
  & .fxp-filings__cv {
    position: absolute;
    inset: 0;
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }

  & .fxp-filings__magnet {
    position: absolute;
    z-index: 1;
    left: calc(var(--x) * 100%);
    top: calc(var(--y) * 100%);
    inline-size: var(--fxp-filings-len);
    block-size: calc(var(--fxp-filings-len) * .26);
    translate: -50% -50%;
    rotate: var(--a);
    display: grid;
    grid-template-columns: 1fr 1fr;
    padding: 0;
    border: 0;
    border-radius: 3px;
    overflow: hidden;
    cursor: grab;
    touch-action: none;
    box-shadow:
      inset 0 1px 0 color-mix(in oklch, white 35%, transparent),
      inset 0 -1px 0 color-mix(in oklch, var(--fxp-filings-iron) 30%, transparent),
      0 1px 2px color-mix(in oklch, var(--fxp-filings-iron) 30%, transparent),
      0 6px 14px -6px color-mix(in oklch, var(--fxp-filings-iron) 45%, transparent);
    transition: rotate .7s var(--fxp-filings-spring), scale .3s var(--fxp-filings-out), box-shadow .3s var(--fxp-filings-out);
  }
  & .fxp-filings__magnet:hover { scale: 1.03; }
  & .fxp-filings__magnet[data-drag] {
    cursor: grabbing;
    scale: 1.06;
    box-shadow:
      inset 0 1px 0 color-mix(in oklch, white 35%, transparent),
      0 2px 3px color-mix(in oklch, var(--fxp-filings-iron) 25%, transparent),
      0 16px 26px -10px color-mix(in oklch, var(--fxp-filings-iron) 55%, transparent);
  }
  & .fxp-filings__magnet:focus-visible {
    outline: 2px solid var(--fxp-filings-iron);
    outline-offset: 3px;
  }
  & .fxp-filings__pole {
    display: grid;
    place-items: center;
    font: 750 clamp(9px, 2.8cqi, 12px)/1 system-ui, sans-serif;
    letter-spacing: .04em;
    color: color-mix(in oklch, white 92%, transparent);
  }
  & .fxp-filings__pole--s { background: linear-gradient(var(--fxp-filings-south), color-mix(in oklch, var(--fxp-filings-south) 82%, var(--fxp-filings-iron))); }
  & .fxp-filings__pole--n { background: linear-gradient(var(--fxp-filings-north), color-mix(in oklch, var(--fxp-filings-north) 82%, var(--fxp-filings-iron))); }

  /* A field probe: the needle follows the pointer and swings to the local field. */
  & .fxp-filings__needle {
    position: absolute;
    z-index: 2;
    left: 0;
    top: 0;
    inline-size: 26px;
    block-size: 26px;
    margin: -13px 0 0 -13px;
    border-radius: 50%;
    background: color-mix(in oklch, var(--fxp-filings-paper) 70%, transparent);
    box-shadow: 0 0 0 1px var(--fxp-filings-line), 0 3px 8px -3px color-mix(in oklch, var(--fxp-filings-iron) 40%, transparent);
    pointer-events: none;
    opacity: 0;
    scale: .6;
    transition: opacity .2s, scale .4s var(--fxp-filings-spring);
  }
  & .fxp-filings__needle i {
    position: absolute;
    inset: 3px;
    rotate: var(--r, 0deg);
    transition: rotate .55s var(--fxp-filings-spring);
    background:
      linear-gradient(90deg, transparent 50%, var(--fxp-filings-north) 50%) center / 18px 2px no-repeat,
      linear-gradient(90deg, var(--fxp-filings-south) 50%, transparent 50%) center / 18px 2px no-repeat;
  }
  &[data-probe] .fxp-filings__needle { opacity: 1; scale: 1; }

  & .fxp-filings__head,
  & .fxp-filings__read,
  & .fxp-filings__hint {
    position: relative;
    z-index: 3;
    margin: 0;
    pointer-events: none;
  }
  & .fxp-filings__head { grid-area: head; min-inline-size: 0; }
  /* a paper halo keeps type legible over the filings */
  & .fxp-filings__head,
  & .fxp-filings__label,
  & .fxp-filings__value,
  & .fxp-filings__hint {
    text-shadow: 0 0 2px var(--fxp-filings-paper), 0 0 6px var(--fxp-filings-paper), 0 0 12px var(--fxp-filings-paper);
  }
  & .fxp-filings__eyebrow {
    margin: 0 0 3px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .13em;
    text-transform: uppercase;
    color: var(--fxp-filings-muted);
  }
  & .fxp-filings__title {
    margin: 0;
    font-family: ui-serif, Georgia, serif;
    font-size: clamp(20px, 6.6cqi, 29px);
    font-weight: 500;
    font-style: italic;
    line-height: 1.02;
    letter-spacing: -0.01em;
    text-wrap: balance;
  }
  & .fxp-filings__read {
    grid-area: read;
    display: grid;
    gap: 6px;
    justify-items: end;
    align-self: start;
  }
  & .fxp-filings__field {
    display: grid;
    justify-items: end;
    gap: 2px;
    margin: 0;
  }
  & .fxp-filings__label {
    font-size: 9.5px;
    font-weight: 650;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxp-filings-muted);
  }
  & .fxp-filings__label em { font-style: normal; font-weight: 500; letter-spacing: .04em; text-transform: none; }
  & .fxp-filings__value {
    font: 500 11px/1 ui-monospace, Menlo, monospace;
    color: var(--fxp-filings-muted);
  }
  & .fxp-filings__value b {
    font-size: clamp(14px, 4.4cqi, 18px);
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: var(--fxp-filings-iron);
  }
  & .fxp-filings__state {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin: 0;
    padding: 3px 8px 3px 6px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    color: var(--fxp-filings-north);
    background: color-mix(in oklch, var(--fxp-filings-north) 11%, var(--fxp-filings-paper));
    transition: color .3s var(--fxp-filings-out), background-color .3s var(--fxp-filings-out);
  }
  & .fxp-filings__state[data-state="repel"] {
    color: color-mix(in oklch, var(--fxp-filings-south) 75%, var(--fxp-filings-iron));
    background: color-mix(in oklch, var(--fxp-filings-south) 14%, var(--fxp-filings-paper));
  }
  & .fxp-filings__state svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxp-filings__ar { transition: opacity .25s, translate .45s var(--fxp-filings-spring); }
  & .fxp-filings__state[data-state="attract"] .fxp-filings__ar--r,
  & .fxp-filings__state[data-state="repel"] .fxp-filings__ar--a { opacity: 0; }

  & .fxp-filings__tools {
    grid-area: tools;
    position: relative;
    z-index: 3;
    display: flex;
    gap: 6px;
    align-self: end;
    justify-self: start;
  }
  & .fxp-filings__tool {
    display: inline-flex;
    white-space: nowrap;
    align-items: center;
    gap: 6px;
    padding: 7px 11px 7px 9px;
    border: 0;
    border-radius: 999px;
    background: var(--fxp-filings-chip);
    box-shadow: inset 0 0 0 1px var(--fxp-filings-line), 0 2px 6px -3px color-mix(in oklch, var(--fxp-filings-iron) 30%, transparent);
    color: var(--fxp-filings-iron);
    font: 600 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .25s var(--fxp-filings-out), scale .3s var(--fxp-filings-out), opacity .5s var(--fxp-filings-out) calc(var(--i) * 70ms + 200ms), translate .7s var(--fxp-filings-out) calc(var(--i) * 70ms + 200ms);
    @starting-style { opacity: 0; translate: 0 8px; }
  }
  & .fxp-filings__tool:hover { background: color-mix(in oklch, var(--fxp-filings-iron) 7%, var(--fxp-filings-paper)); }
  & .fxp-filings__tool:active { scale: .95; }
  & .fxp-filings__tool:focus-visible { outline: 2px solid var(--fxp-filings-north); outline-offset: 2px; }
  & .fxp-filings__tool svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxp-filings__hint {
    grid-area: hint;
    align-self: end;
    padding-block-end: 8px;
    font-size: 10.5px;
    text-align: end;
    color: var(--fxp-filings-muted);
    text-wrap: balance;
    max-inline-size: 16ch;
    transition: opacity .5s var(--fxp-filings-out);
  }
  &[data-used] .fxp-filings__hint { opacity: 0; }
  & .fxp-filings__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 380px) {
  .fxp-filings {
    & .fxp-filings__hint { display: none; }
    & .fxp-filings__tool { padding-inline: 8px 10px; }
  }
}
@container (max-width: 330px) {
  .fxp-filings {
    & .fxp-filings__tool svg { display: none; }
    & .fxp-filings__tool { padding-inline: 10px; }
  }
}
@container (min-width: 560px) {
  .fxp-filings {
    & .fxp-filings__hint { max-inline-size: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxp-filings {
    & .fxp-filings__magnet,
    & .fxp-filings__needle,
    & .fxp-filings__needle i,
    & .fxp-filings__tool,
    & .fxp-filings__ar { transition: none; }
  }
}

js:
/* Iron filings — each bar magnet is modelled as a pair of opposite poles, and
   B is their summed inverse-square field. A filing is an unpolarised needle:
   it feels a torque ∝ |B|·sin 2Δθ, so it lines up with the field but cannot
   tell north from south. Static friction holds everything still until the
   sheet is tapped; only then do filings turn, and creep up the gradient of |B|. */
const sheet = root.querySelector('.fxp-filings__sheet');
const cv = root.querySelector('.fxp-filings__cv');
const ctx = cv.getContext('2d');
const probeEl = root.querySelector('.fxp-filings__probe');
const needle = root.querySelector('.fxp-filings__needle');
const needleI = needle.querySelector('i');
const outB = root.querySelector('[data-k="b"]');
const outWhere = root.querySelector('[data-k="where"]');
const stateEl = root.querySelector('.fxp-filings__state');
const stateTxt = root.querySelector('[data-k="state"]');
const live = root.querySelector('.fxp-filings__sr');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, DEG = Math.PI / 180;
const Q = 4200;                 /* pole strength: |B| ≈ Q / r² in mT, r in px */
const M = [...root.querySelectorAll('.fxp-filings__magnet')].map((el, i) => ({
  el, name: 'Magnet ' + 'AB'[i],
  x: parseFloat(el.style.getPropertyValue('--x')),
  y: parseFloat(el.style.getPropertyValue('--y')),
  a: parseFloat(el.style.getPropertyValue('--a')),
  cx: 0, cy: 0, ux: 1, uy: 0, len: 80, wid: 20,
}));
const poles = new Float32Array(M.length * 6);
let W = 0, H = 0, DPR = 1, NF = 0;
let fx, fy, fa, fl, fg, fb;
let agit = 0, clock = 0, sprinkled = 0, drag = null, suppress = null;
let probe = null, needleAt = 0, attract = null;
/* the opening: two taps once the filings have landed, on the frame clock */
const intro = [[.7, .9], [1.6, .6]];
let raf = 0, last = 0, seen = true, dead = false;
const pal = {};
const bg = document.createElement('canvas'), bgx = bg.getContext('2d');

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probeEl.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probeEl).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
function theme() {
  pal.paper = rgb('--fxp-filings-paper');
  pal.iron = rgb('--fxp-filings-iron');
  pal.grid = rgb('--fxp-filings-grid');
  pal.soft = mix(pal.iron, pal.paper, .38);
  paintBg();
}
/* Squared lab paper with a few fibres, painted once per size/theme. */
function paintBg() {
  if (!W || !pal.paper) return;
  bg.width = cv.width; bg.height = cv.height;
  const g = bgx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  g.fillStyle = css(pal.paper, 1);
  g.fillRect(0, 0, W, H);
  const step = Math.max(12, Math.round(W / 26));
  const o = .5 / DPR;
  for (let pass = 0; pass < 2; pass++) {
    g.beginPath();
    for (let i = 1, x = step; x < W; x += step, i++) if ((i % 5 === 0) === !!pass) { g.moveTo(Math.round(x) + o, 0); g.lineTo(Math.round(x) + o, H); }
    for (let i = 1, y = step; y < H; y += step, i++) if ((i % 5 === 0) === !!pass) { g.moveTo(0, Math.round(y) + o); g.lineTo(W, Math.round(y) + o); }
    g.strokeStyle = css(pal.grid, pass ? .9 : .5);
    g.lineWidth = pass ? 1 / DPR * 1.5 : 1 / DPR;
    g.stroke();
  }
  let s = 4242;
  const r = () => ((s = Math.imul(s ^ (s >>> 15), 0x2c1b3c6d) + 0x297a2d39 | 0) >>> 0) / 4294967296;
  g.lineWidth = .6;
  for (let i = 0, n = Math.round(W * H / 260); i < n; i++) {
    const x = r() * W, y = r() * H, a = r() * TAU, l = 2 + r() * 6;
    g.strokeStyle = css(r() < .5 ? pal.iron : [255, 255, 255], .035);
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); g.stroke();
  }
  const v = g.createRadialGradient(W / 2, H / 2, Math.min(W, H) * .35, W / 2, H / 2, Math.hypot(W, H) * .62);
  v.addColorStop(0, css(pal.iron, 0));
  v.addColorStop(1, css(pal.iron, .07));
  g.fillStyle = v;
  g.fillRect(0, 0, W, H);
}

/* ── field ── */
function updatePoles() {
  let k = 0;
  for (const m of M) {
    m.len = m.el.offsetWidth || 80; m.wid = m.el.offsetHeight || 20;
    const r = m.a * DEG, L = m.len * .4;
    m.ux = Math.cos(r); m.uy = Math.sin(r); m.cx = m.x * W; m.cy = m.y * H;
    poles[k++] = m.cx + m.ux * L; poles[k++] = m.cy + m.uy * L; poles[k++] = 1;
    poles[k++] = m.cx - m.ux * L; poles[k++] = m.cy - m.uy * L; poles[k++] = -1;
  }
}
let BX = 0, BY = 0;
function field(x, y) {
  let bx = 0, by = 0;
  for (let k = 0; k < poles.length; k += 3) {
    const dx = x - poles[k], dy = y - poles[k + 1], r2 = dx * dx + dy * dy + 9;
    const f = poles[k + 2] / (r2 * Math.sqrt(r2));
    bx += dx * f; by += dy * f;
  }
  BX = bx * Q; BY = by * Q;
}
/* Keep filings off the magnets' faces: push out of each rotated rectangle. */
function clear(i) {
  for (const m of M) {
    const dx = fx[i] - m.cx, dy = fy[i] - m.cy;
    const lx = dx * m.ux + dy * m.uy, ly = -dx * m.uy + dy * m.ux;
    const hx = m.len / 2 + 1.5, hy = m.wid / 2 + 1.5;
    if (Math.abs(lx) < hx && Math.abs(ly) < hy) {
      const px = hx - Math.abs(lx), py = hy - Math.abs(ly);
      let nx = lx, ny = ly;
      if (px < py) nx = Math.sign(lx || 1) * hx; else ny = Math.sign(ly || 1) * hy;
      fx[i] = m.cx + nx * m.ux - ny * m.uy;
      fy[i] = m.cy + nx * m.uy + ny * m.ux;
    }
  }
}

function sprinkle(stagger) {
  NF = Math.max(1400, Math.min(4800, Math.round(W * H / 33)));
  fx = new Float32Array(NF); fy = new Float32Array(NF); fa = new Float32Array(NF);
  fl = new Float32Array(NF); fg = new Uint8Array(NF); fb = new Float32Array(NF);
  for (let i = 0; i < NF; i++) {
    fx[i] = Math.random() * W; fy[i] = Math.random() * H;
    fa[i] = Math.random() * Math.PI;
    fl[i] = 2 + Math.random() * Math.random() * 5;
    fg[i] = Math.random() < .3 ? 1 : 0;
    fb[i] = stagger ? Math.random() * Math.random() * .6 : 0;
    clear(i);
  }
  sprinkled = clock;
}
/* Fully settled pattern in one go (reduced motion, and sizing). */
function relax() {
  for (let i = 0; i < NF; i++) {
    field(fx[i], fy[i]);
    const mag = Math.hypot(BX, BY), s = mag / (mag + .2);
    fa[i] = Math.atan2(BY, BX) + (Math.random() - .5) * (1 - s) * 2.4;
  }
}

function step(dt) {
  clock += dt;
  agit *= Math.exp(-dt * 3.2);
  const rate = agit * 18 + (drag ? 2.5 : 0);
  if (rate < .02) return;
  const move = agit > .03;
  for (let i = 0; i < NF; i++) {
    const x = fx[i], y = fy[i];
    field(x, y);
    const bx = BX, by = BY, mag = Math.hypot(bx, by);
    const s = mag / (mag + .25);
    fa[i] += dt * rate * s * Math.sin(2 * (Math.atan2(by, bx) - fa[i])) * .5;
    if (move) {
      field(x + 1.5, y); const m1 = Math.hypot(BX, BY);
      field(x, y + 1.5); const m2 = Math.hypot(BX, BY);
      const gx = (m1 - mag) / 1.5, gy = (m2 - mag) / 1.5, gl = Math.hypot(gx, gy) + 1e-6;
      const st = Math.min(.42, gl * .25) * agit * dt * 60;
      fx[i] += gx / gl * st + (Math.random() - .5) * agit * .7;
      fy[i] += gy / gl * st + (Math.random() - .5) * agit * .7;
      clear(i);
    }
  }
}

function draw() {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.drawImage(bg, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.lineCap = 'round';
  const age = clock - sprinkled;
  for (let pass = 0; pass < 3; pass++) {
    const off = pass === 0 ? .7 : 0;
    ctx.beginPath();
    for (let i = 0; i < NF; i++) {
      if (fb[i] > age) continue;
      if (pass === 1 && fg[i]) continue;
      if (pass === 2 && !fg[i]) continue;
      const h = fl[i] / 2, c = Math.cos(fa[i]) * h, s = Math.sin(fa[i]) * h;
      ctx.moveTo(fx[i] - c + off, fy[i] - s + off);
      ctx.lineTo(fx[i] + c + off, fy[i] + s + off);
    }
    if (pass === 0) { ctx.strokeStyle = css(pal.iron, .1); ctx.lineWidth = 1.7; }
    else if (pass === 1) { ctx.strokeStyle = css(pal.iron, .88); ctx.lineWidth = 1.05; }
    else { ctx.strokeStyle = css(pal.soft, .9); ctx.lineWidth = .85; }
    ctx.stroke();
  }
}

/* ── readouts ── */
function fmt(b) { return b < 10 ? b.toFixed(2) : b < 100 ? b.toFixed(1) : Math.round(b).toString(); }
function readProbe() {
  const p = probe || [W / 2, H / 2];
  field(p[0], p[1]);
  outB.textContent = fmt(Math.hypot(BX, BY));
  outWhere.textContent = probe ? 'at probe' : 'at centre';
  if (probe) {
    needle.style.translate = p[0] + 'px ' + p[1] + 'px';
    const target = Math.atan2(BY, BX) / DEG;
    let d = ((target - needleAt) % 360 + 540) % 360 - 180;
    needleAt += d;
    needleI.style.setProperty('--r', needleAt.toFixed(1) + 'deg');
  }
}
const WINDS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
function label(m) {
  const b = (((m.a + 90) % 360) + 360) % 360;
  m.el.setAttribute('aria-label', m.name + ', north pole facing ' + WINDS[Math.round(b / 45) % 8] +
    '. Arrow keys move it, R turns it, Enter flips it.');
}
/* Dipole–dipole energy U ∝ m₁·m₂ − 3(m₁·r̂)(m₂·r̂): negative means the pair attracts. */
function readState(announce) {
  const [a, b] = M;
  const rx = b.cx - a.cx, ry = b.cy - a.cy, rl = Math.hypot(rx, ry) + 1e-6;
  const hx = rx / rl, hy = ry / rl;
  const U = (a.ux * b.ux + a.uy * b.uy) - 3 * (a.ux * hx + a.uy * hy) * (b.ux * hx + b.uy * hy);
  const now = U < 0;
  if (now === attract) return;
  attract = now;
  stateEl.dataset.state = now ? 'attract' : 'repel';
  stateTxt.textContent = now ? 'Attracting' : 'Repelling';
  if (announce) live.textContent = 'The magnets are now ' + (now ? 'attracting' : 'repelling') + '.';
}
function apply(m, announce) {
  m.el.style.setProperty('--x', m.x.toFixed(4));
  m.el.style.setProperty('--y', m.y.toFixed(4));
  m.el.style.setProperty('--a', m.a + 'deg');
  updatePoles();
  label(m);
  readState(announce);
  readProbe();
  if (calm) { relax(); draw(); }
  kick();
}

/* ── tapping the sheet ── */
function tap(strength) {
  if (calm) { relax(); draw(); return; }
  agit = Math.min(1.2, agit + strength);
  const A = strength * 1.6;
  sheet.animate([
    { translate: '0 0' },
    { translate: (-1.6 * A) + 'px ' + (.9 * A) + 'px' },
    { translate: (1.3 * A) + 'px ' + (-1.1 * A) + 'px' },
    { translate: (-.7 * A) + 'px ' + (.6 * A) + 'px' },
    { translate: (.3 * A) + 'px ' + (-.2 * A) + 'px' },
    { translate: '0 0' },
  ], { duration: 300, easing: 'linear' });
  kick();
}

/* ── host ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W, ow = W, oh = H;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  updatePoles();
  if (first) {
    sprinkle(!calm);
    if (calm) relax();
    M.forEach(label);
    readState(false);
  } else {
    for (let i = 0; i < NF; i++) { fx[i] *= W / ow; fy[i] *= H / oh; clear(i); }
    if (calm) relax();
  }
  paintBg();
  readProbe();
  draw();
}
function busy() { return agit > .01 || drag || clock - sprinkled < .65 || intro.length > 0; }
function kick() {
  if (dead || raf || !seen || document.hidden) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  if (!calm) {
    step(dt);
    while (intro.length && clock >= intro[0][0]) tap(intro.shift()[1]);
  } else clock += dt;
  draw();
  if (busy() && !calm) { if (!raf) raf = requestAnimationFrame(frame); } else last = 0;
}
const ro = new ResizeObserver(([e]) => { size(e.contentRect.width, e.contentRect.height); kick(); });
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; if (calm) { fb.fill(0); relax(); draw(); } kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); draw(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
/* Watchdog: notices unmounting while paused, and gives the sheet an idle tap now and then. */
let idleAt = performance.now();
const dog = setInterval(() => {
  if (!root.isConnected) return teardown();
  if (calm || !seen || document.hidden || drag) return;
  if (performance.now() - idleAt > 9000) { idleAt = performance.now(); tap(.3); }
}, 1500);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}
function used() { idleAt = performance.now(); if (!('used' in root.dataset)) root.dataset.used = ''; }

/* ── magnets: drag, click to flip, wheel or R to turn, arrows to move ── */
M.forEach((m) => {
  const el = m.el;
  el.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    e.preventDefault();
    try { el.setPointerCapture(e.pointerId); } catch (err) { /* synthetic or already released pointer */ }
    drag = { m, id: e.pointerId, sx: e.clientX, sy: e.clientY, ox: m.x, oy: m.y, moved: false };
    el.focus({ preventScroll: true });
    used();
  });
  el.addEventListener('pointermove', (e) => {
    if (!drag || drag.m !== m || drag.id !== e.pointerId) return;
    const dx = e.clientX - drag.sx, dy = e.clientY - drag.sy;
    if (!drag.moved && Math.hypot(dx, dy) < 4) return;
    if (!drag.moved) { drag.moved = true; el.dataset.drag = ''; }
    m.x = Math.max(.1, Math.min(.9, drag.ox + dx / W));
    m.y = Math.max(.2, Math.min(.86, drag.oy + dy / H));
    agit = Math.max(agit, .16);
    apply(m, true);
  });
  const end = (e) => {
    if (!drag || drag.m !== m || drag.id !== e.pointerId) return;
    if (drag.moved) { suppress = m; tap(.25); }
    delete el.dataset.drag;
    drag = null;
  };
  el.addEventListener('pointerup', end);
  el.addEventListener('pointercancel', end);
  el.addEventListener('click', () => {
    if (suppress === m) { suppress = null; return; }
    m.a += 180;
    apply(m, true);
    tap(.2);
    used();
  });
  el.addEventListener('wheel', (e) => {
    e.preventDefault();
    m.a += Math.sign(e.deltaY || e.deltaX) * 15;
    apply(m, true);
    agit = Math.max(agit, .12);
    used();
  }, { passive: false });
  el.addEventListener('keydown', (e) => {
    const s = e.shiftKey ? .06 : .02;
    if (e.key === 'ArrowLeft') m.x = Math.max(.1, m.x - s);
    else if (e.key === 'ArrowRight') m.x = Math.min(.9, m.x + s);
    else if (e.key === 'ArrowUp') m.y = Math.max(.2, m.y - s);
    else if (e.key === 'ArrowDown') m.y = Math.min(.86, m.y + s);
    else if (e.key === 'r' || e.key === 'R') m.a += e.shiftKey ? -15 : 15;
    else return;
    e.preventDefault();
    apply(m, true);
    tap(.18);
    used();
  });
});

/* ── the probe needle follows a hovering pointer ── */
root.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch' || drag) return;
  const r = cv.getBoundingClientRect();
  probe = [e.clientX - r.left, e.clientY - r.top];
  if (!('probe' in root.dataset)) root.dataset.probe = '';
  readProbe();
});
root.addEventListener('pointerleave', () => {
  probe = null;
  delete root.dataset.probe;
  readProbe();
});

root.querySelector('[data-act="tap"]').addEventListener('click', () => { used(); tap(1); live.textContent = 'Sheet tapped.'; });
root.querySelector('[data-act="sprinkle"]').addEventListener('click', () => {
  used();
  sprinkle(!calm);
  if (calm) relax();
  live.textContent = 'Fresh filings sprinkled.';
  if (!calm) intro.push([clock + .65, .8]);
  draw();
  kick();
});

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
if (calm) intro.length = 0;
kick();

css:
.fxp-fireworks {
  /* Re-theme the night with the first three; the four salts are the star colours. */
  --fxp-fireworks-sky: oklch(0.155 0.016 48);
  --fxp-fireworks-haze: oklch(0.31 0.045 48);
  --fxp-fireworks-text: oklch(0.95 0.02 80);
  --fxp-fireworks-sr: oklch(0.66 0.23 25);
  --fxp-fireworks-ba: oklch(0.83 0.2 140);
  --fxp-fireworks-na: oklch(0.86 0.15 78);
  --fxp-fireworks-cu: oklch(0.72 0.14 245);

  --fxp-fireworks-muted: color-mix(in oklch, var(--fxp-fireworks-text) 58%, var(--fxp-fireworks-sky));
  --fxp-fireworks-line: color-mix(in oklch, var(--fxp-fireworks-text) 14%, transparent);
  --fxp-fireworks-well: color-mix(in oklch, var(--fxp-fireworks-sky) 64%, transparent);
  --fxp-fireworks-out: cubic-bezier(.16, 1, .3, 1);
  --fxp-fireworks-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
