    color: color-mix(in oklch, var(--c) 70%, var(--fxp-fireworks-text));
    cursor: pointer;
    transition: background-color .3s var(--fxp-fireworks-out), box-shadow .3s var(--fxp-fireworks-out), translate .45s var(--fxp-fireworks-spring), opacity .5s var(--fxp-fireworks-out) calc(var(--i) * 60ms + 150ms);
