    background: none;
    color: var(--fxp-fireworks-muted);
    font: 600 11px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: color .25s var(--fxp-fireworks-out), background-color .25s var(--fxp-fireworks-out), opacity .5s var(--fxp-fireworks-out) calc(var(--i) * 60ms + 250ms), translate .7s var(--fxp-fireworks-out) calc(var(--i) * 60ms + 250ms);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & .fxp-fireworks__shell svg {
    flex: none;
    inline-size: 14px;
    block-size: 14px;
    fill: none;
