  }
  & .fxp-fireworks__shell:hover { color: var(--fxp-fireworks-text); }
  & .fxp-fireworks__shell[aria-checked="true"] {
    color: var(--fxp-fireworks-text);
    background: color-mix(in oklch, var(--fxp-fireworks-text) 12%, transparent);
  }
  & .fxp-fireworks__shell:focus-visible { outline: 2px solid var(--fxp-fireworks-na); outline-offset: -2px; }
  & .fxp-fireworks__sr {
