@container (max-width: 350px) {
  .fxp-fireworks {
    & .fxp-fireworks__shell svg { display: none; }
    & .fxp-fireworks__salt small { display: none; }
    & .fxp-fireworks__salts { gap: 3px; }
    & .fxp-fireworks__log { max-inline-size: 24ch; }
    & .fxp-fireworks__no,
    & .fxp-fireworks__dia { display: none; }
  }
}
@container (min-width: 560px) {
  .fxp-fireworks {
    & .fxp-fireworks__shells { justify-self: start; grid-template-columns: repeat(4, auto); }
    & .fxp-fireworks__shell { padding-inline: 14px; }
