js:
/* Night shells — every shell is ballistic: launched from the waterline with the
   exact velocity that puts its apex where you tapped, it bursts there into star
   shells laid out on a Fibonacci sphere (so the projected burst has the bright
   limb real photographs show). Stars feel air drag and gravity; trails live on
   an additive layer that fades frame-rate-independently, and that same layer is
   sliced, mirrored, squashed and rippled into the harbour. */
const cv = root.querySelector('.fxp-fireworks__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-fireworks__stage');
const probe = root.querySelector('.fxp-fireworks__probe');
const aimEl = root.querySelector('.fxp-fireworks__aim');
const logEl = root.querySelector('[data-k="log"]');
const live = root.querySelector('.fxp-fireworks__sr');
const saltBtns = [...root.querySelectorAll('.fxp-fireworks__salt')];
const shellBtns = [...root.querySelectorAll('.fxp-fireworks__shell')];
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2;
const SALTS = [['Sr', 'strontium red', '--fxp-fireworks-sr'], ['Ba', 'barium green', '--fxp-fireworks-ba'],
  ['Na', 'sodium gold', '--fxp-fireworks-na'], ['Cu', 'copper blue', '--fxp-fireworks-cu']];
const SHELLS = ['peony', 'willow', 'ring', 'crossette'];
const SKY_M = 210;              /* metres of sky between the waterline and the top edge */
const MAX_SPARKS = 2600;

let W = 0, H = 0, HZ = 0, DPR = 1, G = 100;
const light = document.createElement('canvas'), lx = light.getContext('2d');
const bg = document.createElement('canvas'), bgx = bg.getContext('2d');
const puff = document.createElement('canvas');
const pal = {};
let salt = 0, shell = 0;
const rising = [], groups = [], sparks = [], smoke = [], flashes = [], queue = [];
let clock = 0, nextAuto = .5, lastUser = -99, fired = 0, exposures = 0;
let raf = 0, last = 0, seen = true, dead = false;
const aim = { x: .5, y: .34 };

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
const rand = (a, b) => a + Math.random() * (b - a);

function theme() {
  pal.sky = rgb('--fxp-fireworks-sky');
  pal.haze = rgb('--fxp-fireworks-haze');
  pal.text = rgb('--fxp-fireworks-text');
  pal.salts = SALTS.map((s) => rgb(s[2]));
  pal.gold = mix(pal.salts[2], [255, 150, 60], .35);
  pal.white = [255, 247, 232];
  pal.spark = [pal.gold, pal.white].concat(pal.salts);
  puff.width = puff.height = 64;
  const g = puff.getContext('2d');
  const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  const c = mix(pal.haze, pal.text, .3);
  gr.addColorStop(0, css(c, 1));
  gr.addColorStop(.5, css(c, .45));
  gr.addColorStop(1, css(c, 0));
  g.clearRect(0, 0, 64, 64);
  g.fillStyle = gr;
  g.fillRect(0, 0, 64, 64);
  paintBg();
}

/* Sky with the town's glow on the horizon, the quay, its lit windows and the water. */
function paintBg() {
  if (!W || !pal.sky) return;
  bg.width = cv.width; bg.height = cv.height;
  const g = bgx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  let lg = g.createLinearGradient(0, 0, 0, HZ);
  lg.addColorStop(0, css(pal.sky, 1));
  lg.addColorStop(.7, css(mix(pal.sky, pal.haze, .35), 1));
  lg.addColorStop(1, css(pal.haze, 1));
  g.fillStyle = lg;
  g.fillRect(0, 0, W, HZ + 1);
  lg = g.createLinearGradient(0, HZ, 0, H);
  lg.addColorStop(0, css(mix(pal.haze, pal.sky, .45), 1));
  lg.addColorStop(1, css(mix(pal.sky, [0, 0, 0], .25), 1));
  g.fillStyle = lg;
  g.fillRect(0, HZ, W, H - HZ);
  let s = 77;
  const r = () => ((s = Math.imul(s ^ (s >>> 15), 0x2c1b3c6d) + 0x297a2d39 | 0) >>> 0) / 4294967296;
  for (let i = 0, n = Math.round(W * HZ / 2600); i < n; i++) {
    g.fillStyle = css(pal.text, .08 + r() * .3);
    g.fillRect(r() * W, r() * HZ * .6, .9, .9);
  }
  /* the quay: warehouses, two cranes, lit windows, and their streaks on the water */
  const land = mix(pal.sky, [0, 0, 0], .35);
  g.fillStyle = css(land, 1);
  g.beginPath();
  g.moveTo(0, HZ + 1);
  const lights = [];
  let x = 0;
  while (x < W) {
    const w = 10 + r() * 26, h = (x < W * .4 ? 7 : 3) + r() * (x < W * .4 ? 12 : 7);
    g.lineTo(x, HZ - h); g.lineTo(x + w, HZ - h);
    for (let k = 0; k < w / 6; k++) if (r() < .32) lights.push([x + 2 + r() * (w - 4), HZ - h + 2 + r() * (h - 3)]);
    x += w;
  }
  g.lineTo(W, HZ + 1);
  g.closePath();
  g.fill();
  g.strokeStyle = css(land, 1);
  g.lineWidth = 1.2;
  for (const cx of [W * .12, W * .27]) {
    const top = HZ - 30 - r() * 8;
    g.beginPath();
    g.moveTo(cx, HZ - 6); g.lineTo(cx, top);
    g.moveTo(cx - 6, top + 2); g.lineTo(cx + 24, top + 2);
    g.moveTo(cx, top); g.lineTo(cx + 18, top + 2);
    g.moveTo(cx + 16, top + 2); g.lineTo(cx + 16, top + 9);
    g.stroke();
  }
  for (const [lx0, ly0] of lights) {
    g.fillStyle = css(pal.salts[2], .55 + r() * .4);
    g.fillRect(lx0, ly0, 1.2, 1.2);
    g.fillStyle = css(pal.salts[2], .12);
    g.fillRect(lx0, HZ + (HZ - ly0) * .6 + 1, 1.2, 3 + r() * 6);
  }
  g.fillStyle = css(mix(pal.haze, pal.text, .2), .5);
  g.fillRect(0, HZ, W, 1 / DPR);
}

/* ── shells ── */
function fire(tx, ty, kind, s, user) {
  ty = Math.max(HZ * .1, Math.min(HZ * .62, ty));
  tx = Math.max(W * .06, Math.min(W * .94, tx));
  const h = HZ - ty, T = .95 + .55 * (h / HZ);
  const apex = h / HZ * SKY_M;
  const inch = apex < 110 ? 3 : apex < 150 ? 4 : apex < 190 ? 5 : 6;
  const dia = inch * 25;
  const x0 = tx + rand(-.04, .04) * W;
  rising.push({ x: x0, y: HZ, x0, tx, ty, h, T, t: 0, kind, s, inch, r: dia / 2 * HZ / SKY_M });
  fired++;
  logEl.innerHTML = '<span class="fxp-fireworks__no">№ ' + fired + ' · </span>' + inch + '″ ' + SHELLS[kind] + ' · ' + SALTS[s][0] +
    ' · apex ' + Math.round(apex) + ' m<span class="fxp-fireworks__dia"> · Ø ' + dia + ' m</span>';
  if (user) live.textContent = inch + '-inch ' + SHELLS[kind] + ', ' + SALTS[s][1] + ', bursting at ' + Math.round(apex) + ' metres.';
}
function spark(x, y, vx, vy, c, life, k, g) {
  if (sparks.length >= MAX_SPARKS) return;
  sparks.push({ x, y, px: x, py: y, vx, vy, c, life, max: life, k, g });
}
function star(grp, x, y, vx, vy, life, k, g, extra) {
  grp.stars.push(Object.assign({ x, y, px: x, py: y, vx, vy, life: life * rand(.85, 1.1), max: life, k, g }, extra));
}
function burst(sh) {
  const { x, y, r, kind } = sh;
  const c = pal.salts[sh.s];
  const grp = { c: kind === 1 ? mix(pal.gold, c, .3) : c, stars: [], glitter: kind === 0 && Math.random() < .4 };
  groups.push(grp);
  const rot = Math.random() * TAU;
  if (kind === 0 || kind === 3) {
    const n = kind === 0 ? 92 + sh.inch * 8 : 16, k = kind === 0 ? 1.7 : 1.5;
    for (let i = 0; i < n; i++) {
      const z = 1 - 2 * (i + .5) / n, rr = Math.sqrt(1 - z * z), a = i * 2.39996 + rot;
      const v = k * r * rand(.94, 1.04);
      star(grp, x, y, Math.cos(a) * rr * v, Math.sin(a) * rr * v, kind === 0 ? 1.45 : .62, k, 1,
        kind === 3 ? { cross: 1 } : { z });
    }
  } else if (kind === 1) {
    const n = 64, k = 2.5;
    for (let i = 0; i < n; i++) {
      const z = 1 - 2 * (i + .5) / n, rr = Math.sqrt(1 - z * z), a = i * 2.39996 + rot;
      const v = k * r * 1.08;
      star(grp, x, y, Math.cos(a) * rr * v, Math.sin(a) * rr * v, 2.9, k, .5, { willow: 1 });
    }
  } else {
    const n = 54, k = 1.7, ct = rand(.25, .95);
    for (let i = 0; i < n; i++) {
      const a = i / n * TAU, dx = Math.cos(a), dy = Math.sin(a) * ct;
      const v = k * r;
      star(grp, x, y, (dx * Math.cos(rot) - dy * Math.sin(rot)) * v, (dx * Math.sin(rot) + dy * Math.cos(rot)) * v, 1.4, k, 1);
    }
    const pis = { c: pal.white, stars: [], glitter: false };
    groups.push(pis);
    for (let i = 0; i < 22; i++) {
      const z = 1 - 2 * (i + .5) / 22, rr = Math.sqrt(1 - z * z), a = i * 2.39996;
      const v = 1.7 * r * .34;
      star(pis, x, y, Math.cos(a) * rr * v, Math.sin(a) * rr * v, .9, 1.7, 1);
    }
  }
  flashes.push({ x, y, c, e: 1 });
  for (let i = 0; i < 4; i++) smoke.push({ x: x + rand(-.4, .4) * r, y: y + rand(-.3, .4) * r, s: r * rand(.6, 1.05), life: 1, vx: rand(4, 9), vy: rand(-3, 1) });
}
function split(grp, st) {
  const sp = Math.hypot(st.vx, st.vy) * .5 + 18, base = Math.atan2(st.vy, st.vx);
  for (let q = 0; q < 4; q++) {
    const a = base + Math.PI / 4 + q * Math.PI / 2;
    star(grp, st.x, st.y, Math.cos(a) * sp, Math.sin(a) * sp, .8, 1.9, 1);
  }
  spark(st.x, st.y, 0, 0, 1, .12, 6, 0);
}

function simulate(dt) {
  clock += dt;
  while (queue.length && clock >= queue[0].at) { const q = queue.shift(); fire(q.tx, q.ty, q.kind, q.s, false); }
  for (let i = rising.length - 1; i >= 0; i--) {
    const sh = rising[i];
    sh.t += dt;
    const p = Math.min(sh.t, sh.T), vy0 = -2 * sh.h / sh.T, g = 2 * sh.h / (sh.T * sh.T);
    sh.x = sh.x0 + (sh.tx - sh.x0) * p / sh.T;
    sh.y = HZ + vy0 * p + .5 * g * p * p;
    for (let k = 0; k < 2; k++) spark(sh.x + rand(-.6, .6), sh.y, rand(-8, 8), rand(10, 34), 0, rand(.25, .5), 3, .4);
    if (sh.t >= sh.T) { burst(sh); rising.splice(i, 1); }
  }
  for (let gi = groups.length - 1; gi >= 0; gi--) {
    const grp = groups[gi], list = grp.stars;
    for (let i = list.length - 1; i >= 0; i--) {
      const st = list[i];
      st.life -= dt;
      if (st.life <= 0) {
        if (st.cross) split(grp, st);
        list[i] = list[list.length - 1]; list.pop();
        continue;
      }
      st.px = st.x; st.py = st.y;
      const d = Math.exp(-st.k * dt);
      st.vx *= d; st.vy = st.vy * d + G * st.g * dt;
      st.x += st.vx * dt; st.y += st.vy * dt;
      if (st.willow && Math.random() < .85) spark(st.x, st.y, st.vx * .08, st.vy * .08, 0, rand(.7, 1.3), 2.6, .22);
      if (grp.glitter && st.life < st.max * .7 && Math.random() < .14) spark(st.x, st.y, rand(-6, 6), rand(-6, 6), 1, rand(.1, .22), 4, .2);
    }
    if (!list.length) groups.splice(gi, 1);
  }
  for (let i = sparks.length - 1; i >= 0; i--) {
    const p = sparks[i];
    p.life -= dt;
    if (p.life <= 0) { sparks[i] = sparks[sparks.length - 1]; sparks.pop(); continue; }
    p.px = p.x; p.py = p.y;
    const d = Math.exp(-p.k * dt);
    p.vx *= d; p.vy = p.vy * d + G * p.g * dt;
    p.x += p.vx * dt; p.y += p.vy * dt;
  }
  for (let i = flashes.length - 1; i >= 0; i--) { flashes[i].e *= Math.exp(-dt * 5.5); if (flashes[i].e < .01) flashes.splice(i, 1); }
  for (let i = smoke.length - 1; i >= 0; i--) {
    const m = smoke[i];
    m.life -= dt / 7; m.x += m.vx * dt; m.y += m.vy * dt; m.s += dt * 3;
    if (m.life <= 0) smoke.splice(i, 1);
  }
}

/* Paint the newest motion onto the light layer. */
const LV = [.22, .5, .9];
function ink(fade, dt) {
  lx.setTransform(1, 0, 0, 1, 0, 0);
  if (fade) {
    lx.globalCompositeOperation = 'destination-out';
    lx.fillStyle = 'rgba(0,0,0,' + (1 - Math.exp(-dt * 6.5)).toFixed(4) + ')';
    lx.fillRect(0, 0, light.width, light.height);
  }
  lx.globalCompositeOperation = 'lighter';
  lx.setTransform(DPR, 0, 0, DPR, 0, 0);
  lx.lineCap = 'round';
  const paths = pal.spark.map(() => [new Path2D(), new Path2D(), new Path2D()]);
  for (const p of sparks) {
    const f = p.life / p.max, l = f > .66 ? 2 : f > .33 ? 1 : 0, path = paths[p.c][l];
    path.moveTo(p.px, p.py); path.lineTo(p.x, p.y);
  }
  lx.lineWidth = 1;
  paths.forEach((set, c) => set.forEach((path, l) => { lx.strokeStyle = css(pal.spark[c], LV[l]); lx.stroke(path); }));
  for (const grp of groups) {
    const hot = new Path2D(), dim = new Path2D();
    for (const st of grp.stars) {
      const f = st.life / st.max;
      if (f < .35 && Math.random() < .3) continue;       /* dying stars strobe */
      const path = f > .35 ? hot : dim;
      path.moveTo(st.px, st.py); path.lineTo(st.x, st.y);
    }
    lx.lineWidth = 2.6; lx.strokeStyle = css(grp.c, .32); lx.stroke(hot);
    lx.lineWidth = 1.1; lx.strokeStyle = css(mix(grp.c, pal.white, .5), .95); lx.stroke(hot);
    lx.lineWidth = 1.6; lx.strokeStyle = css(grp.c, .45); lx.stroke(dim);
  }
  for (const sh of rising) {
    lx.fillStyle = css(pal.white, .95);
    lx.fillRect(sh.x - .9, sh.y - .9, 1.8, 1.8);
  }
}

function render() {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  ctx.drawImage(bg, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  let F = 0;
  ctx.globalCompositeOperation = 'lighter';
  for (const f of flashes) {
    F += f.e;
    const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, HZ * .95);
    g.addColorStop(0, css(f.c, .2 * f.e));
    g.addColorStop(1, css(f.c, 0));
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, HZ);
    ctx.save();
    ctx.translate(f.x, HZ + (H - HZ) * .3);
    ctx.scale(1, .22);
    const w = ctx.createRadialGradient(0, 0, 0, 0, 0, W * .5);
    w.addColorStop(0, css(f.c, .16 * f.e));
    w.addColorStop(1, css(f.c, 0));
    ctx.fillStyle = w;
    ctx.fillRect(-W, -W, W * 2, W * 2);
    ctx.restore();
  }
  ctx.globalCompositeOperation = 'source-over';
  for (const m of smoke) {
    ctx.globalAlpha = Math.min(.5, m.life * (.05 + .28 * Math.min(1, F)));
    ctx.drawImage(puff, m.x - m.s, m.y - m.s, m.s * 2, m.s * 2);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'lighter';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  const hz = Math.round(HZ * DPR);
  ctx.drawImage(light, 0, 0, light.width, hz, 0, 0, light.width, hz);
  /* the harbour: 2px strips, each sampling a squashed band of sky from the far side
     of the horizon, displaced by two travelling ripples that grow toward the viewer */
  const band = H - HZ, k = HZ * .9 / band;
  for (let y = HZ; y < H; y += 2) {
    const d = y - HZ, sy = HZ - (d + 2) * k;
    if (sy < 0) break;
    const dx = Math.sin(y * .5 + clock * 2.6) * (.4 + d * .06) + Math.sin(y * 1.7 - clock * 3.3) * .5;
    ctx.globalAlpha = .5 * (1 - d / band * .75);
    ctx.drawImage(light, 0, sy * DPR, light.width, 2 * k * DPR, dx * DPR, y * DPR, light.width, 2 * DPR);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
}

/* ── loop ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W;
  W = w; H = h; HZ = Math.round(H * .67);
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = light.width = Math.round(W * DPR);
  cv.height = light.height = Math.round(H * DPR);
  G = HZ * .45;
  paintBg();
  placeAim();
  if (calm) { exposures = 0; composeStill(); }
  else if (first) {
    /* open mid-show: one shell already climbing, one just burst */
    fire(W * .64, HZ * .34, 0, 0, false);
    for (let i = 0; i < 88; i++) { simulate(1 / 60); ink(true, 1 / 60); }
    fire(W * .3, HZ * .42, 1, 2, false);
    for (let i = 0; i < 30; i++) { simulate(1 / 60); ink(true, 1 / 60); }
    nextAuto = clock + 1.4;
  }
  render();
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 1 / 24) : 1 / 60;
  last = now;
  if (clock >= nextAuto && clock - lastUser > 2.5 && !queue.length) {
    const many = Math.random() < .12 ? 2 : 1;
    for (let i = 0; i < many; i++) fire(rand(.14, .86) * W, rand(.26, .52) * HZ, (Math.random() * 4) | 0, (Math.random() * 4) | 0, false);
    nextAuto = clock + rand(1.1, 2.9);
  }
  simulate(dt);
  ink(true, dt);
  render();
  raf = requestAnimationFrame(frame);
}
/* Reduced motion: a long-exposure photograph, never a moving sky. */
function expose(tx, ty, kind, s, user) {
  if (exposures >= 5) { lx.setTransform(1, 0, 0, 1, 0, 0); lx.clearRect(0, 0, light.width, light.height); exposures = 0; }
  exposures++;
  fire(tx, ty, kind, s, user);
  for (let i = 0; i < 260 && (rising.length || groups.length || sparks.length); i++) { simulate(1 / 60); ink(false, 1 / 60); }
  flashes.length = 0;
  render();
}
function composeStill() {
  lx.setTransform(1, 0, 0, 1, 0, 0);
  lx.clearRect(0, 0, light.width, light.height);
  rising.length = groups.length = sparks.length = smoke.length = flashes.length = queue.length = 0;
  expose(W * .26, HZ * .46, 0, 0, false);
  expose(W * .6, HZ * .36, 1, 2, false);
  expose(W * .84, HZ * .54, 2, 3, false);
  logEl.textContent = 'Long exposure · tap to add a shell';
}
const ro = new ResizeObserver(([e]) => { size(e.contentRect.width, e.contentRect.height); kick(); });
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => {
  calm = mq.matches;
  if (calm) composeStill(); else { lx.setTransform(1, 0, 0, 1, 0, 0); lx.clearRect(0, 0, light.width, light.height); }
  kick();
};
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); render(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
function shoot(x, y) {
  lastUser = clock;
  if (calm) expose(x, y, shell, salt, true); else fire(x, y, shell, salt, true);
}
function finale() {
  lastUser = clock;
  for (let i = 0; i < 6; i++) {
    const tx = W * (.14 + .72 * i / 5) + rand(-12, 12), ty = HZ * rand(.22, .44);
    const kind = i % 2 ? shell : (Math.random() * 4) | 0, s = i % 3 ? salt : (Math.random() * 4) | 0;
    if (calm) { if (i % 2 === 0) expose(tx, ty, kind, s, false); } else queue.push({ at: clock + i * .14, tx, ty, kind, s });
  }
  live.textContent = 'Finale: six shells.';
}
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const r = cv.getBoundingClientRect();
  const x = e.clientX - r.left, y = e.clientY - r.top;
  shoot(x, y < HZ - 8 ? y : HZ * .35);
  aim.x = x / W; aim.y = Math.max(.1, Math.min(.62, (y < HZ - 8 ? y : HZ * .35) / HZ));
  placeAim();
});
function placeAim() { aimEl.style.translate = (aim.x * W).toFixed(1) + 'px ' + (aim.y * HZ).toFixed(1) + 'px'; }
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? .1 : .04;
  if (e.key === 'ArrowLeft') aim.x = Math.max(.06, aim.x - s);
  else if (e.key === 'ArrowRight') aim.x = Math.min(.94, aim.x + s);
  else if (e.key === 'ArrowUp') aim.y = Math.max(.1, aim.y - s);
  else if (e.key === 'ArrowDown') aim.y = Math.min(.62, aim.y + s);
  else if (e.key === 'Enter' || e.key === ' ') { if (e.shiftKey) finale(); else shoot(aim.x * W, aim.y * HZ); }
  else if (e.key === 'Escape') {
    if (calm) { lx.setTransform(1, 0, 0, 1, 0, 0); lx.clearRect(0, 0, light.width, light.height); exposures = 0; render(); }
    queue.length = 0;
    live.textContent = 'Sky cleared.';
  } else return;
  e.preventDefault();
  placeAim();
});
function radio(btns, onPick) {
  btns.forEach((b, i) => {
    const pick = (focus) => {
      btns.forEach((x, j) => { x.setAttribute('aria-checked', String(j === i)); x.tabIndex = j === i ? 0 : -1; });
      if (focus) b.focus();
      onPick(i);
    };
    b.addEventListener('click', () => pick(false));
    b.addEventListener('keydown', (e) => {
      const n = btns.length;
      const to = { ArrowRight: i + 1, ArrowDown: i + 1, ArrowLeft: i - 1, ArrowUp: i - 1, Home: 0, End: n - 1 }[e.key];
      if (to === undefined) return;
      e.preventDefault();
      btns[(to + n) % n].click();
      btns[(to + n) % n].focus();
    });
  });
}
radio(saltBtns, (i) => { salt = i; });
radio(shellBtns, (i) => { shell = i; });

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxp-snow {
  /* Re-theme with these three. */
  --fxp-snow-night: oklch(0.2 0.024 172);
  --fxp-snow-lamp: oklch(0.79 0.15 68);
  --fxp-snow-flake: oklch(0.97 0.008 240);

  --fxp-snow-sign: color-mix(in oklch, var(--fxp-snow-lamp) 12%, oklch(0.4 0.016 172));
  --fxp-snow-text: color-mix(in oklch, var(--fxp-snow-flake) 88%, var(--fxp-snow-lamp));
  --fxp-snow-muted: color-mix(in oklch, var(--fxp-snow-text) 58%, var(--fxp-snow-night));
  --fxp-snow-line: color-mix(in oklch, var(--fxp-snow-text) 15%, transparent);
  --fxp-snow-well: color-mix(in oklch, var(--fxp-snow-night) 62%, transparent);
  --fxp-snow-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head tools" ". .";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 288px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-snow-night);
  color: var(--fxp-snow-text);
  font-family: system-ui, sans-serif;

  & .fxp-snow__cv,
  & .fxp-snow__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-snow__cv { display: block; }
  & .fxp-snow__stage {
    z-index: 1;
    cursor: ew-resize;
    touch-action: pan-y;
    outline: none;
    border-radius: inherit;
  }
  & .fxp-snow__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxp-snow-lamp), inset 0 0 0 5px color-mix(in oklch, var(--fxp-snow-lamp) 20%, transparent);
  }

  & .fxp-snow__head {
    grid-area: head;
    position: relative;
    z-index: 2;
    min-inline-size: 0;
    pointer-events: none;
  }
  & .fxp-snow__eyebrow {
    margin: 0 0 8px;
    white-space: nowrap;
    font-size: 10px;
    font-weight: 650;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxp-snow-muted);
  }
  /* The canvas sets the word itself; the heading stays for assistive tech. */
  & .fxp-snow__title {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    margin: 0;
  }
  & .fxp-snow__obs {
    display: grid;
    grid-auto-flow: column;
    justify-content: start;
    gap: clamp(10px, 3.6cqi, 18px);
    margin: 0;
  }
  & .fxp-snow__obs div {
    display: grid;
    gap: 3px;
    transition: opacity .6s var(--fxp-snow-out), translate .8s var(--fxp-snow-out);
    @starting-style { opacity: 0; translate: 0 4px; }
  }
  & .fxp-snow__obs div:nth-child(2) { transition-delay: 70ms; }
  & .fxp-snow__obs div:nth-child(3) { transition-delay: 140ms; }
  & .fxp-snow__obs dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-snow-muted);
  }
  & .fxp-snow__obs dd {
    margin: 0;
    font: 500 12px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }
  & .fxp-snow__obs b { font-weight: 650; }

  & .fxp-snow__tools {
    grid-area: tools;
    position: relative;
    z-index: 2;
    display: grid;
    gap: 8px;
    justify-items: end;
    align-self: start;
  }
  & .fxp-snow__rate {
    display: grid;
    grid-template-columns: auto auto;
    grid-template-areas: "name out" "range range";
    justify-content: space-between;
    align-items: baseline;
    gap: 2px 10px;
    inline-size: clamp(124px, 36cqi, 160px);
    padding: 7px 10px 5px;
    border-radius: 10px;
    background: var(--fxp-snow-well);
    box-shadow: inset 0 0 0 1px var(--fxp-snow-line);
    backdrop-filter: blur(6px);
  }
  & .fxp-snow__rate-name {
    grid-area: name;
    font-size: 9px;
    font-weight: 650;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-snow-muted);
  }
  & .fxp-snow__rate output {
    grid-area: out;
    white-space: nowrap;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxp-snow__rate input {
    grid-area: range;
    inline-size: 100%;
    margin: 4px 0 0;
    accent-color: var(--fxp-snow-lamp);
    cursor: pointer;
  }
  & .fxp-snow__rate:has(input:focus-visible) {
    box-shadow: inset 0 0 0 1.5px var(--fxp-snow-lamp);
  }
  & .fxp-snow__rate input:focus-visible { outline: none; }
  & .fxp-snow__shake {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px 6px 8px;
    border: 0;
    border-radius: 999px;
    background: var(--fxp-snow-well);
    box-shadow: inset 0 0 0 1px var(--fxp-snow-line);
    color: var(--fxp-snow-text);
    font: 600 11px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .25s var(--fxp-snow-out), scale .3s var(--fxp-snow-out);
  }
  & .fxp-snow__shake:hover { background: color-mix(in oklch, var(--fxp-snow-lamp) 22%, var(--fxp-snow-night)); }
  & .fxp-snow__shake:active { scale: .95; }
  & .fxp-snow__shake:focus-visible { outline: 2px solid var(--fxp-snow-lamp); outline-offset: 2px; }
  & .fxp-snow__shake svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxp-snow__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 340px) {
  .fxp-snow {
    & .fxp-snow__obs div:nth-child(3) { display: none; }
    & .fxp-snow__eyebrow { letter-spacing: .06em; font-size: 9.5px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxp-snow {
    & .fxp-snow__obs div,
    & .fxp-snow__shake { transition: none; }
  }
}

js:
/* Snowline — three depth layers of snow. The far layer drifts behind the sign,
   the near layer is out-of-focus bokeh in front of it, and the middle layer lands.
   The word is rasterised once into a 2px occupancy grid; a flake that reaches a
   solid cell becomes a grain that obeys a sandpile automaton: it slides
   diagonally while it can (a 45° angle of repose, softened by a little
   cohesion), caps stop growing at a few grains, and a grain pushed off the edge
   of a letter falls again as a loose chunk onto whatever lies below. */
const cv = root.querySelector('.fxp-snow__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-snow__stage');
const probe = root.querySelector('.fxp-snow__probe');
const outWind = root.querySelector('[data-k="wind"]');
const outDir = root.querySelector('[data-k="dir"]');
const outSettled = root.querySelector('[data-k="settled"]');
const outRate = root.querySelector('[data-k="rate"]');
const rateIn = root.querySelector('.fxp-snow__rate input');
const live = root.querySelector('.fxp-snow__sr');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2;
const C = 2;                      /* grid cell, CSS px */
const WORD = 'SNOWLINE';
const CAP_SIGN = 5, CAP_GROUND = 9;
let W = 0, H = 0, DPR = 1, cols = 0, rows = 0, groundRow = 0, G = null;
let far = [], mid = [], near = [], loose = [];
let rate = 2.4, wind = 14, windT = 14, gustT = 0, settled = 0, shake = 0, ptrX = .5;
let clock = 0, readClock = 0, raf = 0, last = 0, seen = true, dead = false;
const pal = {};
const bg = document.createElement('canvas'), bgx = bg.getContext('2d');
const sign = document.createElement('canvas'), sgx = sign.getContext('2d');
const snowL = document.createElement('canvas'), snx = snowL.getContext('2d');
const bokeh = document.createElement('canvas');
const maskC = document.createElement('canvas'), mkx = maskC.getContext('2d', { willReadFrequently: true });
let Lx = 0, Ly = 0;

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
const rand = (a, b) => a + Math.random() * (b - a);

/* How much of the sodium lamp, spilling in from beyond the top-right corner, reaches (x, y). */
function lampF(x, y) {
  const dx = x - Lx, dy = y - Ly, d = Math.hypot(dx, dy) + 1e-3;
  const c = (dx * -.5 + dy * .866) / d;
  const k = Math.min(1, Math.max(0, (c - .72) / .24));
  return k * k * (3 - 2 * k) / (1 + (d / (H * 1.25)) ** 2);
}

function theme() {
  pal.night = rgb('--fxp-snow-night');
  pal.lamp = rgb('--fxp-snow-lamp');
  pal.flake = rgb('--fxp-snow-flake');
  pal.sign = rgb('--fxp-snow-sign');
  pal.lit = mix(pal.flake, pal.lamp, .42);
  bokeh.width = bokeh.height = 48;
  const g = bokeh.getContext('2d');
  g.clearRect(0, 0, 48, 48);
  const gr = g.createRadialGradient(24, 24, 0, 24, 24, 24);
  gr.addColorStop(0, css(pal.flake, .9));
  gr.addColorStop(.55, css(pal.flake, .55));
  gr.addColorStop(.8, css(pal.flake, .18));
  gr.addColorStop(1, css(pal.flake, 0));
  g.fillStyle = gr;
  g.fillRect(0, 0, 48, 48);
  if (W) { paintBg(); paintSign(); repaintSnow(); }
}

function paintBg() {
  bg.width = cv.width; bg.height = cv.height;
  const g = bgx;
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const lg = g.createLinearGradient(0, 0, 0, H);
  lg.addColorStop(0, css(mix(pal.night, [0, 0, 0], .3), 1));
  lg.addColorStop(1, css(mix(pal.night, pal.flake, .07), 1));
  g.fillStyle = lg;
  g.fillRect(0, 0, W, H);
  /* far ridge of spruce, two tones of distance */
  let s = 3141;
  const r = () => ((s = Math.imul(s ^ (s >>> 15), 0x2c1b3c6d) + 0x297a2d39 | 0) >>> 0) / 4294967296;
  for (let layer = 0; layer < 2; layer++) {
    const base = H * (layer ? .9 : .8), tone = mix(pal.night, layer ? [0, 0, 0] : pal.flake, layer ? .35 : .06);
    g.fillStyle = css(tone, 1);
    g.beginPath();
    g.moveTo(0, H);
    for (let x = -6; x < W + 12;) {
      const h = (layer ? 16 : 10) + r() * (layer ? 22 : 14), w = 5 + r() * 7;
      g.lineTo(x, base); g.lineTo(x + w / 2, base - h); g.lineTo(x + w, base);
      x += w * (.55 + r() * .5);
    }
    g.lineTo(W, H);
    g.closePath();
    g.fill();
  }
  /* the lamp's cone: a conic falloff across the beam multiplied by a radial one along it */
  const cone = document.createElement('canvas');
  cone.width = bg.width; cone.height = bg.height;
  const k = cone.getContext('2d');
  k.setTransform(DPR, 0, 0, DPR, 0, 0);
  const a0 = Math.atan2(.866, -.5);
  if (k.createConicGradient) {
    const cg = k.createConicGradient(a0 - .75, Lx, Ly);
    [[0, 0], [.04, .25], [.08, .75], [.12, 1], [.16, .75], [.2, .25], [.24, 0], [1, 0]].forEach(([o, a]) => cg.addColorStop(o, css(pal.lamp, a)));
    k.fillStyle = cg;
  } else k.fillStyle = css(pal.lamp, .6);
  k.fillRect(0, 0, W, H);
  k.globalCompositeOperation = 'destination-in';
  const rg = k.createRadialGradient(Lx, Ly, 0, Lx, Ly, H * 1.35);
  rg.addColorStop(0, 'rgba(0,0,0,.42)');
  rg.addColorStop(.45, 'rgba(0,0,0,.12)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  k.fillStyle = rg;
  k.fillRect(0, 0, W, H);
  g.setTransform(1, 0, 0, 1, 0, 0);
  g.globalCompositeOperation = 'lighter';
  g.drawImage(cone, 0, 0);
  g.globalCompositeOperation = 'source-over';
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
}

/* The word: one raster for the occupancy grid (CSS px), one lit copy to draw (device px). */
let layout = null;
function measure() {
  mkx.font = '900 100px system-ui, sans-serif';
  const wid = [...WORD].map((ch) => mkx.measureText(ch).width);
  const track = 1.5;
  const total = wid.reduce((a, b) => a + b, 0) + track * (WORD.length - 1);
  const fs = Math.min(W * .88 / total * 100, H * .34);
  const k = fs / 100;
  const x0 = (W - total * k) / 2, base = H * .62 + fs * .36;
  const xs = [];
  let x = x0;
  wid.forEach((w) => { xs.push(x); x += (w + track) * k; });
  layout = { fs, xs, base, top: base - fs * .72 };
}
function drawWord(g, fill) {
  g.font = '900 ' + layout.fs + 'px system-ui, sans-serif';
  g.textBaseline = 'alphabetic';
  g.fillStyle = fill;
  [...WORD].forEach((ch, i) => g.fillText(ch, layout.xs[i], layout.base));
}
function paintSign() {
  sign.width = cv.width; sign.height = cv.height;
  sgx.setTransform(DPR, 0, 0, DPR, 0, 0);
  drawWord(sgx, css(mix(pal.sign, pal.lamp, .5), 1));
  sgx.translate(0, 1.2);
  const lg = sgx.createLinearGradient(0, layout.top, 0, layout.base);
  lg.addColorStop(0, css(mix(pal.sign, pal.lamp, .14), 1));
  lg.addColorStop(1, css(mix(pal.sign, pal.night, .45), 1));
  drawWord(sgx, lg);
  sgx.setTransform(DPR, 0, 0, DPR, 0, 0);
  sgx.globalCompositeOperation = 'source-atop';
  const lit = sgx.createRadialGradient(Lx, Ly, 0, Lx, Ly, H * 1.2);
  lit.addColorStop(0, css(pal.lamp, .4));
  lit.addColorStop(1, css(pal.lamp, 0));
  sgx.fillStyle = lit;
  sgx.fillRect(0, 0, W, H);
  sgx.globalCompositeOperation = 'source-over';
}
function buildGrid() {
  cols = Math.ceil(W / C); rows = Math.ceil(H / C);
  G = new Uint8Array(cols * rows);
  maskC.width = Math.max(1, Math.round(W)); maskC.height = Math.max(1, Math.round(H));
  mkx.clearRect(0, 0, maskC.width, maskC.height);
  drawWord(mkx, '#000');
  const d = mkx.getImageData(0, 0, maskC.width, maskC.height).data;
  for (let y = 0; y < rows; y++) {
    const py = Math.min(maskC.height - 1, y * C + 1);
    for (let x = 0; x < cols; x++) {
      const px = Math.min(maskC.width - 1, x * C + 1);
      if (d[(py * maskC.width + px) * 4 + 3] > 120) G[y * cols + x] = 1;
    }
  }
  groundRow = rows - 3;
  for (let y = groundRow; y < rows; y++) for (let x = 0; x < cols; x++) G[y * cols + x] = 1;
}

/* ── snow on the sign ── */
function paintCell(x, y) {
  const px = x * C + C / 2, py = y * C + C / 2, f = lampF(px, py);
  snx.fillStyle = css(mix(pal.flake, pal.lamp, Math.min(.5, f * .55)), .9 + Math.random() * .1);
  snx.beginPath();
  snx.arc(px, py, C * .98, 0, TAU);
  snx.fill();
}
function repaintSnow() {
  snowL.width = cv.width; snowL.height = cv.height;
  snx.setTransform(DPR, 0, 0, DPR, 0, 0);
  if (!G) return;
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) if (G[y * cols + x] === 2) paintCell(x, y);
}
function spill(x, y) {
  if (loose.length < 500) loose.push({ x: x * C + 1, y: y * C + 1, vx: rand(-6, 6) + wind * .15, vy: rand(4, 16) });
}
/* A grain arrives at cell (x, y). Returns true if it stayed. */
function land(x, y, online) {
  for (let guard = 0; guard < 80; guard++) {
    while (y + 1 < rows && G[(y + 1) * cols + x] === 0) y++;
    if (y + 1 >= rows) return false;
    let k = 0;
    while (y > 0 && G[y * cols + x] !== 0 && k < 4) { y--; k++; }
    if (G[y * cols + x] !== 0) return false;
    if (Math.random() < .22) break;                    /* cohesion: sometimes it simply sticks */
    const b = (y + 1) * cols, row = y * cols;
    const l = x > 0 && G[b + x - 1] === 0 && G[row + x - 1] === 0;
    const r = x < cols - 1 && G[b + x + 1] === 0 && G[row + x + 1] === 0;
    if (!l && !r) break;
    x += l && r ? (Math.random() < .5 ? -1 : 1) : l ? -1 : 1;
    y++;
    if (y + 1 < rows && G[(y + 1) * cols + x] === 0 && online) { spill(x, y); return false; }
  }
  let h = 0, yy = y + 1;
  while (yy < rows && G[yy * cols + x] === 2) { h++; yy++; }
  if (h >= (yy >= groundRow ? CAP_GROUND : CAP_SIGN)) return false;
  G[y * cols + x] = 2;
  paintCell(x, y);
  settled++;
  return true;
}
function presettle(n) {
  for (let i = 0; i < n; i++) land((Math.random() * cols) | 0, 0, false);
}
function brush(px, py, radius, all) {
  let n = 0;
  const r2 = radius * radius;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const i = y * cols + x;
      if (G[i] !== 2) continue;
      const cx = x * C + 1, cy = y * C + 1;
      if (all ? y >= groundRow - CAP_GROUND - 1 : (cx - px) ** 2 + (cy - py) ** 2 > r2) continue;
      G[i] = 0; n++;
      if (!calm && loose.length < 900) {
        const away = all ? rand(-25, 25) : (cx - px) * 2.2 + rand(-20, 20);
        loose.push({ x: cx, y: cy, vx: away, vy: all ? rand(-30, 5) : rand(-80, -25) });
      }
    }
  }
  settled -= n;
  repaintSnow();
  return n;
}

/* ── flakes ── */
function flake(layer, scatter) {
  const f = { x: Math.random() * W, y: scatter ? Math.random() * H : -rand(4, 40), ph: Math.random() * TAU, fq: rand(.6, 1.5) };
  if (layer === 0) Object.assign(f, { r: rand(.5, 1.05), v: rand(11, 19), a: rand(.25, .5) });
  else if (layer === 1) Object.assign(f, { r: rand(1, 1.7), v: rand(26, 40), a: rand(.75, 1) });
  else Object.assign(f, { r: rand(4, 9), v: rand(62, 95), a: rand(.16, .32) });
  return f;
}
function populate() {
  const area = W * H;
  far = Array.from({ length: Math.round(area / 650) }, () => flake(0, true));
  mid = Array.from({ length: Math.round(area / 700) }, () => flake(1, true));
  near = Array.from({ length: 14 }, () => flake(2, true));
}
function active(list) { return Math.max(1, Math.round(list.length * Math.min(1, .08 + rate / 5 * .92))); }

function step(dt) {
  clock += dt;
  gustT += dt;
  wind += (windT - wind) * (1 - Math.exp(-dt * 1.6));
  const wv = wind + 6 * Math.sin(gustT * .7) + 4 * Math.sin(gustT * 1.9 + 1);
  const layers = [[far, .35, 6], [mid, .7, 9], [near, 1.15, 14]];
  layers.forEach(([list, par, amp], li) => {
    const n = active(list);
    for (let i = 0; i < list.length; i++) {
      const f = list[i];
      if (f.y < -900) { if (i < n) Object.assign(f, flake(li, false)); else continue; }
      f.x += (wv * par + Math.sin(clock * f.fq + f.ph) * amp) * dt;
      f.y += f.v * dt;
      if (f.x < -12) f.x += W + 24; else if (f.x > W + 12) f.x -= W + 24;
      if (f.y > H + f.r) { if (i < n) Object.assign(f, flake(li, false)); else f.y = -1000; continue; }
      if (li === 1) {
        const cx = Math.floor(f.x / C), cy = Math.floor(f.y / C);
        if (cx >= 0 && cx < cols && cy >= 0 && cy + 1 < rows && (G[(cy + 1) * cols + cx] !== 0 || G[cy * cols + cx] !== 0)) {
          land(cx, cy, true);
          if (i < n) Object.assign(f, flake(1, false)); else f.y = -1000;
        }
      }
    }
  });
  for (let i = loose.length - 1; i >= 0; i--) {
    const p = loose[i];
    p.vy += 220 * dt;
    p.vx *= Math.exp(-dt * 1.5);
    p.x += p.vx * dt; p.y += p.vy * dt;
    const cx = Math.floor(p.x / C), cy = Math.floor(p.y / C);
    if (p.y > H || cx < 0 || cx >= cols) { loose.splice(i, 1); continue; }
    if (cy >= 0 && cy + 1 < rows && p.vy > 0 && (G[(cy + 1) * cols + cx] !== 0 || G[cy * cols + cx] !== 0)) {
      land(cx, cy, true);
      loose.splice(i, 1);
    }
  }
  shake *= Math.exp(-dt * 7);
  return wv;
}

function draw(wv) {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.drawImage(bg, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  dots(far, 0);
  const sx = shake ? Math.sin(clock * 70) * shake * 3 : 0;
  ctx.setTransform(1, 0, 0, 1, sx * DPR, 0);
  ctx.drawImage(sign, 0, 0);
  ctx.drawImage(snowL, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  dots(mid, 1);
  ctx.fillStyle = css(pal.flake, .95);
  for (const p of loose) ctx.fillRect(p.x - 1.2, p.y - 1.2, 2.4, 2.4);
  const n = active(near), px = (ptrX - .5) * 22;
  for (let i = 0; i < near.length; i++) {
    const f = near[i];
    if (f.y < -900) continue;
    const d = f.r * 2.4;
    ctx.globalAlpha = f.a * (i < n ? 1 : .6) * (1 + lampF(f.x, f.y) * 1.2);
    ctx.drawImage(bokeh, f.x + px * (f.r / 9) - d / 2, f.y - d / 2, d, d);
  }
  ctx.globalAlpha = 1;
}
function dots(list, layer) {
  const lit = new Path2D(), dim = new Path2D();
  const n = calm ? active(list) : list.length;
  for (let i = 0; i < n; i++) {
    const f = list[i];
    if (f.y < -900) continue;
    const p = lampF(f.x, f.y) > .22 ? lit : dim;
    if (layer === 0) p.rect(f.x - f.r, f.y - f.r, f.r * 2, f.r * 2);
    else { p.moveTo(f.x + f.r, f.y); p.arc(f.x, f.y, f.r, 0, TAU); }
  }
  ctx.fillStyle = css(pal.flake, layer ? .9 : .38);
  ctx.fill(dim);
  ctx.fillStyle = css(pal.lit, layer ? 1 : .7);
  ctx.fill(lit);
}
function readout(wv) {
  const kmh = Math.round(Math.abs(wv) * .33);
  outWind.textContent = kmh;
  outDir.textContent = kmh === 0 ? '–' : wv > 0 ? 'W' : 'E';
  outSettled.textContent = settled.toLocaleString('en-US');
}

/* ── host ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const keep = settled;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  Lx = W * 1.04; Ly = -H * .1;
  measure();
  paintBg();
  paintSign();
  buildGrid();
  repaintSnow();
  settled = 0;
  loose = [];
  /* the ground is already white: two rows of old snow, unevenly */
  for (let x = 0; x < cols; x++) {
    const h = 2 + (Math.sin(x * .21) + Math.sin(x * .07 + 2) > 1.2 ? 1 : 0);
    for (let k = 1; k <= h; k++) { G[(groundRow - k) * cols + x] = 2; paintCell(x, groundRow - k); settled++; }
  }
  presettle(Math.max(0, keep - settled) || (calm ? 1500 : 520));
  populate();
  readout(wind);
  draw(wind);
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 1 / 24) : 1 / 60;
  last = now;
  const wv = step(dt);
  draw(wv);
  readClock += dt;
  if (readClock > .25) { readClock = 0; readout(wv); }
  raf = requestAnimationFrame(frame);
}
const ro = new ResizeObserver(([e]) => { size(e.contentRect.width, e.contentRect.height); kick(); });
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; loose = []; draw(wind); kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); draw(wind); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input: drag for wind, tap to knock snow off ── */
let press = null;
function local(e) { const r = cv.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const [x, y] = local(e);
  press = { id: e.pointerId, x, y, w: windT, moved: false };
  try { stage.setPointerCapture(e.pointerId); } catch (err) { /* synthetic or already released pointer */ }
});
stage.addEventListener('pointermove', (e) => {
  const [x] = local(e);
  ptrX = x / Math.max(1, W);
  if (!press || press.id !== e.pointerId) return;
  if (Math.abs(x - press.x) > 5) press.moved = true;
  if (press.moved) windT = Math.max(-70, Math.min(70, press.w + (x - press.x) * .9));
});
stage.addEventListener('pointerup', (e) => {
  if (!press || press.id !== e.pointerId) return;
  if (!press.moved) {
    const n = brush(press.x, press.y, 26, false);
    if (n) live.textContent = n + ' grains knocked off.';
    if (calm) draw(wind);
  } else live.textContent = 'Wind ' + Math.round(Math.abs(windT) * .33) + ' kilometres per hour from the ' + (windT >= 0 ? 'west' : 'east') + '.';
  press = null;
});
stage.addEventListener('pointercancel', () => { press = null; });
stage.addEventListener('pointerleave', () => { ptrX = .5; });
function shakeSign() {
  const n = brush(0, 0, 0, true);
  shake = 1;
  live.textContent = n ? 'Sign shaken: ' + n + ' grains fell.' : 'Nothing to shake off yet.';
  if (calm) draw(wind);
}
stage.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') windT = Math.max(-70, windT - 10);
  else if (e.key === 'ArrowRight') windT = Math.min(70, windT + 10);
  else if (e.key === 'Enter' || e.key === ' ') shakeSign();
  else if (e.key === 'Escape') windT = 14;
  else return;
  e.preventDefault();
});
root.querySelector('.fxp-snow__shake').addEventListener('click', shakeSign);
rateIn.addEventListener('input', () => {
  rate = +rateIn.value;
  outRate.textContent = rate.toFixed(1) + ' cm/h';
  if (calm) draw(wind);
});

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxp-sand {
  /* Re-theme with these four. */
  --fxp-sand-gravel: oklch(0.885 0.013 82);
  --fxp-sand-stone: oklch(0.32 0.012 250);
  --fxp-sand-moss: oklch(0.56 0.1 128);
  --fxp-sand-cedar: oklch(0.5 0.11 48);

  --fxp-sand-ink: color-mix(in oklch, var(--fxp-sand-stone) 92%, black);
  --fxp-sand-muted: color-mix(in oklch, var(--fxp-sand-stone) 64%, var(--fxp-sand-gravel));
  --fxp-sand-line: color-mix(in oklch, var(--fxp-sand-stone) 14%, transparent);
  --fxp-sand-chip: color-mix(in oklch, var(--fxp-sand-gravel) 70%, white);
  --fxp-sand-leaf: color-mix(in oklch, var(--fxp-sand-stone) 40%, var(--fxp-sand-moss));
  --fxp-sand-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head stats" ". ." "tools tools";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 288px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-sand-gravel);
  color: var(--fxp-sand-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxp-sand-line);

  & .fxp-sand__cv,
  & .fxp-sand__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-sand__cv { display: block; }
  & .fxp-sand__stage {
    z-index: 2;
    cursor: crosshair;
    touch-action: none;
    outline: none;
    border-radius: inherit;
  }
  & .fxp-sand__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxp-sand-cedar), inset 0 0 0 5px color-mix(in oklch, var(--fxp-sand-cedar) 20%, transparent);
  }

  /* Leaf shadow from a maple outside the frame, drifting with the breeze. */
  & .fxp-sand__dapple {
    position: absolute;
    inset: -20% -20% 30% 35%;
    z-index: 1;
    pointer-events: none;
    mix-blend-mode: multiply;
    filter: blur(7px);
    opacity: .5;
  }
  & .fxp-sand__dapple i {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(14% 10% at 30% 40%, var(--fxp-sand-leaf) 60%, transparent 62%),
      radial-gradient(10% 13% at 52% 30%, var(--fxp-sand-leaf) 58%, transparent 61%),
      radial-gradient(12% 9% at 70% 55%, var(--fxp-sand-leaf) 60%, transparent 63%),
      radial-gradient(9% 11% at 44% 66%, var(--fxp-sand-leaf) 58%, transparent 61%),
      radial-gradient(11% 8% at 82% 28%, var(--fxp-sand-leaf) 60%, transparent 63%);
    opacity: calc(.55 - var(--i) * .12);
    rotate: calc(var(--i) * 37deg);
    scale: calc(1 + var(--i) * .18);
    animation: fxp-sand-sway calc(9s + var(--i) * 4s) cubic-bezier(.45, 0, .55, 1) calc(var(--i) * -3s) infinite alternate;
  }

  & .fxp-sand__head,
  & .fxp-sand__stats {
    position: relative;
    z-index: 3;
    margin: 0;
    pointer-events: none;
  }
  & .fxp-sand__head { grid-area: head; min-inline-size: 0; }
  & .fxp-sand__eyebrow {
    margin: 0 0 3px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .13em;
    text-transform: uppercase;
    color: var(--fxp-sand-muted);
  }
  & .fxp-sand__title {
    margin: 0;
    font-size: clamp(19px, 6.2cqi, 27px);
    font-weight: 500;
    line-height: 1.02;
    letter-spacing: .04em;
    text-wrap: balance;
  }
  & .fxp-sand__stats {
    grid-area: stats;
    display: grid;
    grid-auto-flow: column;
    gap: clamp(10px, 3.6cqi, 16px);
    align-self: start;
    text-align: end;
  }
  & .fxp-sand__stats div {
    display: grid;
    gap: 3px;
    transition: opacity .6s var(--fxp-sand-out) calc(var(--i) * 80ms + 150ms), translate .8s var(--fxp-sand-out) calc(var(--i) * 80ms + 150ms);
    @starting-style { opacity: 0; translate: 0 -5px; }
  }
  & .fxp-sand__stats dt {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-sand-muted);
  }
  & .fxp-sand__stats dd {
    margin: 0;
    font: 600 clamp(12px, 3.8cqi, 15px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxp-sand__tools {
    grid-area: tools;
