    background: color-mix(in oklch, var(--fxp-sand-chip) 82%, transparent);
    box-shadow: inset 0 0 0 1px var(--fxp-sand-line), 0 4px 14px -6px color-mix(in oklch, var(--fxp-sand-stone) 40%, transparent);
  }
  & .fxp-sand__tool {
    display: inline-flex;
    align-items: center;
