    color: var(--fxp-sand-muted);
    font: 600 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: color .25s var(--fxp-sand-out), background-color .25s var(--fxp-sand-out), opacity .5s var(--fxp-sand-out) calc(var(--i) * 60ms + 250ms);
