/* Karesansui — the gravel is real grains, about one per 1.6 px², laid on a jittered
   lattice so the bed starts dead level. A tine is a small disc dragged through
   them: every grain inside it is pushed sideways, perpendicular to the stroke,
   to the disc's edge, which digs a groove and heaps a ridge either side. The
   board pulls grains back toward their lattice home. Each frame the grains are
   splatted into a density grid, blurred into a height map and lit from the
   top-left as relief, so ridges catch the light and grooves fall into shadow. */
const cv = root.querySelector('.fxp-sand__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-sand__stage');
const probe = root.querySelector('.fxp-sand__probe');
const outGrains = root.querySelector('[data-k="grains"]');
const outRaked = root.querySelector('[data-k="raked"]');
const toolBtns = [...root.querySelectorAll('.fxp-sand__tool')];
const live = root.querySelector('.fxp-sand__sr');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2;
const SP = 1.25;                  /* lattice spacing of the grains, px */
const S = 2;                      /* height-map cell, px */
const CG = 8;                     /* grain bucket, px */
const TC = 6;                     /* coverage cell, px */
const TOOLS = [
  { name: 'rake', tines: 5, gap: 7, r: 2.5 },
  { name: 'stick', tines: 1, gap: 0, r: 3.8 },
  { name: 'board', board: true, hw: 22, hd: 4 },
];
let tool = 0;
let W = 0, H = 0, DPR = 1, N = 0;
let gx, gy, hx, hy;
let gw = 0, gh = 0, dens, tmp, img, noise;
let bcols = 0, brows = 0, bStart, bCur, bItems, bCell;
let tw = 0, th = 0, touched, open = 1, rakedN = 0;
let stones = [];
let dirty = true, raf = 0, last = 0, seen = true, dead = false;
const pal = {};
const hm = document.createElement('canvas'), hmx = hm.getContext('2d');
const grain = document.createElement('canvas');
const rocks = document.createElement('canvas');
const head = { x: 0, y: 0, dx: 1, dy: 0, show: 0, down: false };
let drag = null, auto = null, kb = false;

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * k));
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}

function theme() {
  pal.gravel = rgb('--fxp-sand-gravel');
  pal.stone = rgb('--fxp-sand-stone');
  pal.moss = rgb('--fxp-sand-moss');
  pal.cedar = rgb('--fxp-sand-cedar');
  pal.lit = mix(pal.gravel, [255, 255, 255], .62);
  pal.shade = mix(pal.gravel, pal.stone, .34);
  if (W) { paintRocks(); dirty = true; }
}

/* ── the bed ── */
function layout() {
  const m = Math.min(W, H), r = rng(19);
  const spec = [[.3, .55, .13], [.73, .67, .095], [.8, .31, .06]];
  stones = spec.map(([x, y, s], k) => {
    const R = m * s, n = 15, poly = [];
    for (let i = 0; i < n; i++) {
      const a = i / n * TAU, w = 1 + (r() - .5) * .22 + Math.sin(a * 2 + k) * .06;
      poly.push([Math.cos(a) * R * w * 1.12, Math.sin(a) * R * w * .9]);
    }
    return { x: W * x, y: H * y, r: R, poly, ring: R };
  });
}
function insideStone(x, y, pad) {
  for (const s of stones) {
    const dx = (x - s.x) / 1.12, dy = (y - s.y) / .9;
    if (dx * dx + dy * dy < (s.r + pad) * (s.r + pad)) return true;
  }
  return false;
}
function seed() {
  const r = rng(7);
  const cx = Math.floor(W / SP), cy = Math.floor(H / SP);
  const xs = [], ys = [];
  for (let j = 0; j < cy; j++) for (let i = 0; i < cx; i++) {
    const x = (i + .5 + (r() - .5) * .8) * SP, y = (j + .5 + (r() - .5) * .8) * SP;
    if (insideStone(x, y, -1)) continue;
    xs.push(x); ys.push(y);
  }
  N = xs.length;
  gx = Float32Array.from(xs); gy = Float32Array.from(ys);
  hx = Float32Array.from(xs); hy = Float32Array.from(ys);
  bCell = new Int32Array(N); bItems = new Int32Array(N);
  outGrains.textContent = N.toLocaleString('en-US');
}
/* Grids sized to the bed. On a resize the old coverage map is resampled, so the
   Raked figure keeps describing what is actually on the bed. */
function buffers() {
  const r = rng(11);
  bcols = Math.ceil(W / CG) + 1; brows = Math.ceil(H / CG) + 1;
  bStart = new Int32Array(bcols * brows + 1); bCur = new Int32Array(bcols * brows);
  gw = Math.ceil(W / S) + 2; gh = Math.ceil(H / S) + 2;
  dens = new Float32Array(gw * gh); tmp = new Float32Array(gw * gh);
  noise = new Float32Array(gw * gh);
  for (let i = 0; i < noise.length; i++) noise[i] = (r() - .5) * .07;
  hm.width = gw; hm.height = gh;
  img = hmx.createImageData(gw, gh);
  const old = touched, ow = tw, oh = th;
  tw = Math.ceil(W / TC); th = Math.ceil(H / TC);
  touched = new Uint8Array(tw * th);
  open = 0; rakedN = 0;
  for (let j = 0; j < th; j++) for (let i = 0; i < tw; i++) {
    if (insideStone((i + .5) * TC, (j + .5) * TC, 0)) continue;
    open++;
    if (old && ow && oh) {
      const oi = Math.min(ow - 1, Math.floor(i * ow / tw)), oj = Math.min(oh - 1, Math.floor(j * oh / th));
      if (old[oj * ow + oi]) { touched[j * tw + i] = 1; rakedN++; }
    }
  }
  dirty = true;
}
/* Counting sort of grains into 8px buckets: O(N), once per frame of raking. */
function bucket() {
  const nb = bcols * brows;
  bStart.fill(0);
  for (let i = 0; i < N; i++) {
    let c = (gx[i] / CG) | 0, r = (gy[i] / CG) | 0;
    c = c < 0 ? 0 : c >= bcols ? bcols - 1 : c;
    r = r < 0 ? 0 : r >= brows ? brows - 1 : r;
    const k = r * bcols + c;
    bCell[i] = k; bStart[k + 1]++;
  }
  for (let k = 1; k <= nb; k++) bStart[k] += bStart[k - 1];
  bCur.set(bStart.subarray(0, nb));
  for (let i = 0; i < N; i++) bItems[bCur[bCell[i]]++] = i;
}
function mark(x, y, on) {
  const i = (x / TC) | 0, j = (y / TC) | 0;
  if (i < 0 || j < 0 || i >= tw || j >= th) return;
  const k = j * tw + i;
  if (on && !touched[k]) { touched[k] = 1; rakedN++; } else if (!on && touched[k]) { touched[k] = 0; rakedN--; }
}
function each(x0, y0, x1, y1, fn) {
  const c0 = Math.max(0, (x0 / CG) | 0), c1 = Math.min(bcols - 1, (x1 / CG) | 0);
  const r0 = Math.max(0, (y0 / CG) | 0), r1 = Math.min(brows - 1, (y1 / CG) | 0);
  for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
    const k = r * bcols + c;
    for (let q = bStart[k]; q < bStart[k + 1]; q++) fn(bItems[q]);
  }
}
/* One tine at q moving along d: grains inside the disc go sideways to its rim. */
function tine(qx, qy, dx, dy, r, zone) {
  for (const s of stones) {
    const ex = (qx - s.x) / 1.12, ey = (qy - s.y) / .9, lim = zone ? s.ring : s.r + r * .6;
    if (ex * ex + ey * ey < lim * lim) return;
  }
  const nx = -dy, ny = dx, r2 = r * r;
  each(qx - r, qy - r, qx + r, qy + r, (i) => {
    const ex = gx[i] - qx, ey = gy[i] - qy, al = ex * dx + ey * dy, lat = ex * nx + ey * ny;
    if (al * al + lat * lat >= r2) return;
    const side = lat > 0 ? 1 : lat < 0 ? -1 : (Math.random() < .5 ? -1 : 1);
    const nl = side * Math.sqrt(r2 - al * al) * (1 + Math.random() * .3);
    gx[i] = qx + dx * al + nx * nl;
    gy[i] = qy + dy * al + ny * nl;
  });
  mark(qx, qy, true);
}
function board(qx, qy, dx, dy, t) {
  const nx = -dy, ny = dx, R = t.hw;
  each(qx - R, qy - R, qx + R, qy + R, (i) => {
    const ex = gx[i] - qx, ey = gy[i] - qy, al = ex * dx + ey * dy, lat = ex * nx + ey * ny;
    if (Math.abs(al) > t.hd || Math.abs(lat) > t.hw) return;
    gx[i] += (hx[i] - gx[i]) * .45;
    gy[i] += (hy[i] - gy[i]) * .45;
  });
  for (let k = -t.hw; k <= t.hw; k += TC * .8) mark(qx + nx * k, qy + ny * k, false);
}
/* Move the tool head to (x, y), working every few pixels along the way. */
function strokeTo(x, y, zone) {
  const t = TOOLS[tool], dx = x - head.x, dy = y - head.y, len = Math.hypot(dx, dy);
  if (len < .05) return;
  const k = Math.min(1, len / 6);
  head.dx += (dx / len - head.dx) * k; head.dy += (dy / len - head.dy) * k;
  const hl = Math.hypot(head.dx, head.dy) || 1;
  head.dx /= hl; head.dy /= hl;
  const stepLen = t.board ? 2 : t.r * .55, n = Math.max(1, Math.ceil(len / stepLen));
  const ox = head.x, oy = head.y, nx = -head.dy, ny = head.dx;
  for (let s = 1; s <= n; s++) {
    const px = ox + dx * s / n, py = oy + dy * s / n;
    if (t.board) board(px, py, head.dx, head.dy, t);
    else for (let q = 0; q < t.tines; q++) {
      const off = (q - (t.tines - 1) / 2) * t.gap;
      tine(px + nx * off, py + ny * off, head.dx, head.dy, t.r, zone);
    }
  }
  head.x = x; head.y = y;
  dirty = true;
}

/* ── relief ── */
function relief() {
  dens.fill(0);
  for (let i = 0; i < N; i++) {
    const x = gx[i] / S, y = gy[i] / S, ix = x | 0, iy = y | 0;
    if (ix < 0 || iy < 0 || ix >= gw - 1 || iy >= gh - 1) continue;
    const fx = x - ix, fy = y - iy, k = iy * gw + ix;
    dens[k] += (1 - fx) * (1 - fy); dens[k + 1] += fx * (1 - fy);
    dens[k + gw] += (1 - fx) * fy; dens[k + gw + 1] += fx * fy;
  }
  for (let y = 0; y < gh; y++) {
    const o = y * gw;
    for (let x = 1; x < gw - 1; x++) tmp[o + x] = (dens[o + x - 1] + dens[o + x] * 2 + dens[o + x + 1]) * .25;
    tmp[o] = dens[o]; tmp[o + gw - 1] = dens[o + gw - 1];
  }
  for (let y = 1; y < gh - 1; y++) {
    const o = y * gw;
    for (let x = 0; x < gw; x++) dens[o + x] = (tmp[o + x - gw] + tmp[o + x] * 2 + tmp[o + x + gw]) * .25;
  }
  const mean = (S / SP) * (S / SP), inv = 1 / mean, d = img.data;
  const L = pal.lit, D = pal.shade;
  for (let y = 1; y < gh - 1; y++) {
    for (let x = 1; x < gw - 1; x++) {
      const k = y * gw + x, h = dens[k] * inv;
      const sx = (dens[k + 1] - dens[k - 1]) * inv, sy = (dens[k + gw] - dens[k - gw]) * inv;
      let s = .6 + sx * .42 + sy * .52 - (h < 1 ? (1 - h) * .22 : 0) + noise[k];
      s = s < 0 ? 0 : s > 1 ? 1 : s;
      const p = k * 4;
      d[p] = D[0] + (L[0] - D[0]) * s;
      d[p + 1] = D[1] + (L[1] - D[1]) * s;
      d[p + 2] = D[2] + (L[2] - D[2]) * s;
      d[p + 3] = 255;
    }
  }
  hmx.putImageData(img, 0, 0);
}

function paintGrain() {
  grain.width = cv.width; grain.height = cv.height;
  const g = grain.getContext('2d'), id = g.createImageData(grain.width, grain.height), d = id.data;
  const r = rng(3);
  for (let i = 0; i < d.length; i += 4) {
    const v = r();
    if (v < .16) { d[i] = d[i + 1] = d[i + 2] = 0; d[i + 3] = 30 + v * 300; }
    else if (v > .9) { d[i] = d[i + 1] = d[i + 2] = 255; d[i + 3] = 90; }
  }
  g.putImageData(id, 0, 0);
}
function paintRocks() {
  rocks.width = cv.width; rocks.height = cv.height;
  const g = rocks.getContext('2d');
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const r = rng(5);
  for (const s of stones) {
    g.save();
    g.translate(s.x, s.y);
    /* moss collar */
    for (let i = 0; i < 90; i++) {
      const a = r() * TAU, d = s.r * (1.02 + r() * .16);
      g.fillStyle = css(mix(pal.moss, pal.stone, r() * .35), .5 + r() * .4);
      g.beginPath();
      g.arc(Math.cos(a) * d * 1.12, Math.sin(a) * d * .9 + s.r * .08, 1 + r() * 2.6, 0, TAU);
      g.fill();
    }
    const path = new Path2D();
    s.poly.forEach(([x, y], i) => (i ? path.lineTo(x, y) : path.moveTo(x, y)));
    path.closePath();
    g.shadowColor = css(pal.stone, .45);
    g.shadowBlur = 9 * DPR;
    g.shadowOffsetX = 4 * DPR;
    g.shadowOffsetY = 5 * DPR;
    g.fillStyle = css(pal.stone, 1);
    g.fill(path);
    g.shadowColor = 'transparent';
    const lg = g.createRadialGradient(-s.r * .4, -s.r * .45, 0, 0, 0, s.r * 1.25);
    lg.addColorStop(0, css(mix(pal.stone, pal.gravel, .42), 1));
    lg.addColorStop(.55, css(pal.stone, 1));
    lg.addColorStop(1, css(mix(pal.stone, [0, 0, 0], .35), 1));
    g.fillStyle = lg;
    g.fill(path);
    g.clip(path);
    for (let i = 0; i < 70; i++) {
      g.fillStyle = css(r() < .5 ? pal.gravel : [0, 0, 0], .08 + r() * .1);
      g.fillRect((r() - .5) * s.r * 2.2, (r() - .5) * s.r * 2, 1 + r() * 1.5, 1 + r() * 1.5);
    }
    g.restore();
  }
}

function draw() {
  if (dirty) { relief(); dirty = false; }
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.globalAlpha = 1;
  /* height-map node (i, j) sits at (i·S, j·S): centre each texel on its node */
  ctx.drawImage(hm, 0, 0, gw, gh, -.5 * S * DPR, -.5 * S * DPR, gw * S * DPR, gh * S * DPR);
  ctx.globalAlpha = .55;
  ctx.drawImage(grain, 0, 0);
  ctx.globalAlpha = 1;
  ctx.drawImage(rocks, 0, 0);
  if (head.show > .02) {
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    ctx.globalAlpha = head.show;
    const t = TOOLS[tool], nx = -head.dy, ny = head.dx;
    ctx.translate(head.x, head.y);
    ctx.lineCap = 'round';
    ctx.strokeStyle = css(pal.cedar, 1);
    if (t.board) {
      ctx.lineWidth = 3.5;
      ctx.beginPath(); ctx.moveTo(nx * t.hw, ny * t.hw); ctx.lineTo(-nx * t.hw, -ny * t.hw); ctx.stroke();
    } else {
      const half = (t.tines - 1) / 2 * t.gap + 3;
      ctx.lineWidth = 2.6;
      ctx.beginPath(); ctx.moveTo(nx * half, ny * half); ctx.lineTo(-nx * half, -ny * half); ctx.stroke();
      ctx.fillStyle = css(mix(pal.cedar, [0, 0, 0], .3), 1);
      for (let q = 0; q < t.tines; q++) {
        const off = (q - (t.tines - 1) / 2) * t.gap;
        ctx.beginPath(); ctx.arc(nx * off, ny * off, t.tines > 1 ? 1.4 : 2.2, 0, TAU); ctx.fill();
      }
    }
    ctx.lineWidth = 1.8;
    ctx.strokeStyle = css(mix(pal.cedar, pal.gravel, .25), head.down ? .9 : .5);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-head.dx * 30, -head.dy * 30); ctx.stroke();
    ctx.globalAlpha = 1;
  }
  outRaked.textContent = Math.round(rakedN / Math.max(1, open) * 100) + '%';
}

/* ── the opening: the garden is raked as you watch — rings first, then lines ── */
function plan(ringOnly) {
  const t = TOOLS[0], width = (t.tines - 1) * t.gap, pts = [];
  const list = ringOnly ? [ringOnly] : stones;
  for (const s of list) {
    const rings = s.r > Math.min(W, H) * .1 ? 2 : 1;
    let outer = 0;
    for (let k = 0; k < rings; k++) {
      const rho = s.r + 7 + width / 2 + k * (width + 6), n = Math.ceil(TAU * rho / 3), a0 = Math.random() * TAU;
      for (let j = 0; j <= n + 4; j++) {
        const a = a0 + j / n * TAU;
        pts.push({ x: s.x + Math.cos(a) * rho * 1.12, y: s.y + Math.sin(a) * rho * .9, up: j === 0, zone: false });
      }
      outer = rho + width / 2;
    }
    if (!ringOnly) s.ring = outer + 3;
  }
  if (ringOnly) return pts;
  let dir = 1;
  for (let y = 12 + width / 2; y < H - 8; y += width + 7) {
    const x0 = dir > 0 ? -12 : W + 12, x1 = dir > 0 ? W + 12 : -12, n = Math.ceil(Math.abs(x1 - x0) / 3);
    for (let j = 0; j <= n; j++) pts.push({ x: x0 + (x1 - x0) * j / n, y, up: j === 0, zone: true });
    dir = -dir;
  }
  return pts;
}
function runAuto(dt) {
  const speed = 680, own = tool;
  let budget = dt * speed;
  tool = 0;                                           /* the opening is always raked with the rake */
  bucket();
  while (auto && budget > 0) {
    const p = auto.pts[auto.i];
    if (!p) { auto = null; break; }
    if (p.up) {
      head.x = p.x; head.y = p.y; auto.i++;
      const q = auto.pts[auto.i];
      if (q) { const l = Math.hypot(q.x - p.x, q.y - p.y) || 1; head.dx = (q.x - p.x) / l; head.dy = (q.y - p.y) / l; }
      continue;
    }
    const d = Math.hypot(p.x - head.x, p.y - head.y);
    strokeTo(p.x, p.y, p.zone);
    budget -= d;
    auto.i++;
  }
  tool = own;
}
function finishAutoNow() { while (auto) runAuto(40 / 680); }

/* ── host ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W;
  if (!first && Math.abs(w - W) < 1 && Math.abs(h - H) < 1) return;
  const sx = first ? 1 : w / W, sy = first ? 1 : h / H;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  const rings = stones.map((st) => st.ring / st.r);
  layout();
  stones.forEach((st, k) => { if (rings[k]) st.ring = st.r * rings[k]; });
  if (first) seed();
  else {
    /* keep the raked bed: every grain and its home scale with the frame */
    for (let i = 0; i < N; i++) { gx[i] *= sx; gy[i] *= sy; hx[i] *= sx; hy[i] *= sy; }
    head.x *= sx; head.y *= sy;
    if (auto) auto.pts.forEach((p) => { p.x *= sx; p.y *= sy; });
  }
  buffers();
  paintGrain();
  paintRocks();
  if (first) {
    head.x = W / 2; head.y = H / 2;
    auto = { pts: plan(null), i: 0 };
  }
  if (calm && auto) { finishAutoNow(); head.show = 0; }
