}
function kick() {
  if (dead || raf || !seen || document.hidden) return;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden) { last = 0; return; }
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  if (auto) {
    if (calm) finishAutoNow(); else runAuto(dt);
    head.show = Math.min(1, head.show + dt * 4);
  } else {
    const want = drag || kb ? 1 : 0;
    head.show += (want - head.show) * (calm ? 1 : 1 - Math.exp(-dt * 8));
