/* ── input ── */
function local(e) { const r = cv.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
function stopAuto() { if (auto) { auto = null; live.textContent = 'You have the rake.'; } }
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  stopAuto();
  try { stage.setPointerCapture(e.pointerId); } catch (err) { /* synthetic or already released pointer */ }
  const [x, y] = local(e);
  drag = { id: e.pointerId };
  head.x = x; head.y = y; head.down = true;
  kick();
});
stage.addEventListener('pointermove', (e) => {
  if (!drag || drag.id !== e.pointerId) return;
  const [x, y] = local(e);
  bucket();
  strokeTo(x, y, false);
  if (calm) draw();
  kick();
});
function release(e) {
  if (!drag || drag.id !== e.pointerId) return;
  drag = null; head.down = false;
  live.textContent = 'Raked ' + outRaked.textContent + ' of the bed.';
  kick();
}
stage.addEventListener('pointerup', release);
stage.addEventListener('pointercancel', release);
stage.addEventListener('focus', () => { if (stage.matches(':focus-visible')) { kb = true; kick(); } });
stage.addEventListener('blur', () => { kb = false; head.down = false; kick(); });
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 15 : 5;
  const mv = { ArrowLeft: [-s, 0], ArrowRight: [s, 0], ArrowUp: [0, -s], ArrowDown: [0, s] }[e.key];
  kb = true;
  if (mv) {
    stopAuto();
    const x = Math.max(4, Math.min(W - 4, head.x + mv[0])), y = Math.max(4, Math.min(H - 4, head.y + mv[1]));
    if (head.down) { bucket(); strokeTo(x, y, false); }
    else { head.x = x; head.y = y; head.dx = Math.sign(mv[0]); head.dy = Math.sign(mv[1]); }
  } else if (e.key === ' ') {
    stopAuto();
    head.down = !head.down;
    live.textContent = head.down ? 'Rake lowered.' : 'Rake lifted.';
  } else if (e.key === 'Enter') {
    let best = stones[0], bd = Infinity;
    for (const st of stones) { const d = Math.hypot(st.x - head.x, st.y - head.y); if (d < bd) { bd = d; best = st; } }
    tool = 0; sync();
    auto = { pts: plan(best), i: 0 };
    live.textContent = 'Raking rings around the stone.';
  } else if (e.key === 'Escape') {
    auto = null; head.down = false;
    live.textContent = 'Rake lifted.';
  } else return;
