  toolBtns.forEach((b, i) => { b.setAttribute('aria-checked', String(i === tool)); b.tabIndex = i === tool ? 0 : -1; });
}
toolBtns.forEach((b, i) => {
  b.addEventListener('click', () => { tool = i; sync(); });
  b.addEventListener('keydown', (e) => {
    const n = toolBtns.length;
    const to = { ArrowRight: i + 1, ArrowDown: i + 1, ArrowLeft: i - 1, ArrowUp: i - 1, Home: 0, End: n - 1 }[e.key];
    if (to === undefined) return;
    e.preventDefault();
    tool = (to + n) % n; sync(); toolBtns[tool].focus();
  });
});

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxp-fluid {
  /* Re-theme with the first two; the three liquids are their own colours. */
  --fxp-fluid-bench: oklch(0.968 0.006 95);
  --fxp-fluid-ink: oklch(0.3 0.02 250);
  --fxp-fluid-water: oklch(0.74 0.07 218);
  --fxp-fluid-oil: oklch(0.79 0.14 104);
  --fxp-fluid-honey: oklch(0.7 0.155 62);

  --fxp-fluid-muted: color-mix(in oklch, var(--fxp-fluid-ink) 60%, var(--fxp-fluid-bench));
  --fxp-fluid-line: color-mix(in oklch, var(--fxp-fluid-ink) 13%, transparent);
  --fxp-fluid-well: color-mix(in oklch, var(--fxp-fluid-ink) 5%, var(--fxp-fluid-bench));
  --fxp-fluid-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head meta" "tank tank" "bar bar";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 8px 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 296px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(120% 70% at 50% 100%, color-mix(in oklch, var(--fxp-fluid-ink) 6%, transparent), transparent 70%),
    var(--fxp-fluid-bench);
  color: var(--fxp-fluid-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxp-fluid-line);

  & .fxp-fluid__head { grid-area: head; min-inline-size: 0; }
  & .fxp-fluid__eyebrow {
    margin: 0 0 3px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-fluid-muted);
    text-wrap: balance;
  }
  & .fxp-fluid__title {
    margin: 0;
    font-size: clamp(19px, 6.2cqi, 27px);
    font-weight: 700;
    line-height: 1.02;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }
  & .fxp-fluid__meta {
    grid-area: meta;
    display: grid;
    gap: 5px;
    margin: 0;
    align-self: start;
    text-align: end;
  }
  & .fxp-fluid__meta div {
    display: grid;
    gap: 2px;
    transition: opacity .6s var(--fxp-fluid-out) calc(var(--i) * 80ms + 120ms), translate .8s var(--fxp-fluid-out) calc(var(--i) * 80ms + 120ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxp-fluid__meta dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxp-fluid-muted);
  }
  & .fxp-fluid__sym {
    font-family: ui-serif, Georgia, serif;
    font-size: 11px;
    text-transform: none;
    letter-spacing: 0;
  }
  & .fxp-fluid__meta dd {
    margin: 0;
    font: 600 12.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxp-fluid__tank {
    grid-area: tank;
    position: relative;
    min-block-size: 0;
    margin-inline: -14px;
  }
  & .fxp-fluid__cv,
  & .fxp-fluid__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-fluid__cv { display: block; }
  & .fxp-fluid__stage {
    cursor: grab;
    touch-action: none;
    outline: none;
  }
  & .fxp-fluid__stage:active { cursor: grabbing; }
  & .fxp-fluid__stage:focus-visible {
    outline: 2px solid var(--fxp-fluid-honey);
    outline-offset: -4px;
    border-radius: 12px;
  }

  & .fxp-fluid__bar {
    grid-area: bar;
    display: flex;
    align-items: center;
    gap: 10px;
    min-inline-size: 0;
  }
  & .fxp-fluid__liquids {
    display: grid;
    grid-auto-flow: column;
    gap: 2px;
    padding: 3px;
    border-radius: 999px;
    background: var(--fxp-fluid-well);
    box-shadow: inset 0 0 0 1px var(--fxp-fluid-line);
  }
  & .fxp-fluid__liquid {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 10px 6px 7px;
    border: 0;
    border-radius: 999px;
    background: none;
    color: var(--fxp-fluid-muted);
    font: 600 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: color .25s var(--fxp-fluid-out), background-color .25s var(--fxp-fluid-out), box-shadow .25s var(--fxp-fluid-out);
  }
  & .fxp-fluid__liquid i {
    inline-size: 10px;
    block-size: 10px;
    border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
    background: radial-gradient(circle at 35% 30%, color-mix(in oklch, var(--c) 40%, white), var(--c) 60%);
    box-shadow: 0 0 0 1px color-mix(in oklch, var(--c) 60%, var(--fxp-fluid-ink));
    transition: scale .45s var(--fxp-fluid-out);
  }
  & .fxp-fluid__liquid:hover { color: var(--fxp-fluid-ink); }
  & .fxp-fluid__liquid:hover i { scale: 1.2; }
  & .fxp-fluid__liquid[aria-checked="true"] {
    color: var(--fxp-fluid-ink);
    background: var(--fxp-fluid-bench);
    box-shadow: 0 1px 3px color-mix(in oklch, var(--fxp-fluid-ink) 18%, transparent), inset 0 0 0 1px var(--fxp-fluid-line);
  }
  & .fxp-fluid__liquid:focus-visible { outline: 2px solid var(--c); outline-offset: 1px; }
  & .fxp-fluid__tilt {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 6px;
    min-inline-size: 0;
    color: var(--fxp-fluid-muted);
  }
  & .fxp-fluid__tilt svg {
    flex: none;
    inline-size: 15px;
    block-size: 15px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
  }
  & .fxp-fluid__tilt input {
    flex: 1;
    min-inline-size: 40px;
    margin: 0;
    accent-color: var(--fxp-fluid-ink);
    cursor: pointer;
  }
  & .fxp-fluid__tilt input:focus-visible { outline: 2px solid var(--fxp-fluid-ink); outline-offset: 3px; border-radius: 4px; }
  & .fxp-fluid__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

@container (max-width: 350px) {
  .fxp-fluid {
    & .fxp-fluid__liquid { padding-inline: 6px 8px; gap: 4px; }
    & .fxp-fluid__tilt svg { display: none; }
    & .fxp-fluid__eyebrow { letter-spacing: .08em; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxp-fluid {
    & .fxp-fluid__meta div,
    & .fxp-fluid__liquid,
    & .fxp-fluid__liquid i { transition: none; }
  }
}

js:
/* Viscosity — particle-based fluid after Clavet, Beaudoin & Poulin (2005).
   Each 1/120 s step: gravity, pairwise viscosity impulses (linear σ and
   quadratic β terms on the approaching velocity), position prediction, then
   double-density relaxation, which pushes neighbours apart in proportion to how
   far the local density sits above rest and adds a near-pressure term that
   keeps particles from clumping and gives the surface its tension. Velocities
   are recovered from the change in position. The tank tilts as a body, so the
   liquid stays level in screen space while the glass turns under it.
   Rendering: particles are splatted into a 4px field and contoured with
   marching squares into one filled path plus its surface line. */
const tank = root.querySelector('.fxp-fluid__tank');
const cv = root.querySelector('.fxp-fluid__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-fluid__stage');
const probe = root.querySelector('.fxp-fluid__probe');
const outEta = root.querySelector('[data-k="eta"]');
const outTilt = root.querySelector('[data-k="tilt"]');
const tiltIn = root.querySelector('.fxp-fluid__tilt input');
const liqBtns = [...root.querySelectorAll('.fxp-fluid__liquid')];
const live = root.querySelector('.fxp-fluid__sr');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const DEG = Math.PI / 180, TAU = Math.PI * 2;
const LIQ = [
  { name: 'Water', eta: '1.0 cP', sigma: 0, beta: .03, k: .2, kn: .6, wall: .02, v: '--fxp-fluid-water', alpha: .58 },
  { name: 'Olive oil', eta: '84 cP', sigma: .2, beta: .1, k: .18, kn: .55, wall: .12, v: '--fxp-fluid-oil', alpha: .8 },
  { name: 'Honey', eta: '10,000 cP', sigma: .9, beta: .35, k: .16, kn: .5, wall: .6, v: '--fxp-fluid-honey', alpha: .92 },
];
const TMAX = 15, GS = 4, MAXN = 48;
let liq = 2;
let W = 0, H = 0, DPR = 1, bw = 0, bh = 0, cx = 0, cy = 0, pad = 4, rc = 12;
let h = 18, s = 8, rho0 = 4, N = 0, G = .09;
let X, Y, PX, PY, VX, VY, NB, NC, ghead, gnext, gcols = 0, grows = 0;
let fc = 0, fr = 0, F = null;
let tilt = 0, tiltT = 0, tiltV = 0, idleT = 0, clock = 0, acc = 0;
let stir = null, raf = 0, last = 0, seen = true, dead = false;
const pal = {};
let colCur = null;

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * k);
function theme() {
  pal.bench = rgb('--fxp-fluid-bench');
  pal.ink = rgb('--fxp-fluid-ink');
  pal.liq = LIQ.map((l) => rgb(l.v));
  if (!colCur) colCur = pal.liq[liq].slice();
}

/* ── geometry ── */
function size(w, hh) {
  if (w < 2 || hh < 2) return;
  const first = !W;
  if (!first && Math.abs(w - W) < 1 && Math.abs(hh - H) < 1) return;
  W = w; H = hh;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  /* the largest tank that still fits the frame at full tilt */
  const c = Math.cos(TMAX * DEG), sn = Math.sin(TMAX * DEG);
  bw = Math.min(W * .64, 380);
  bh = Math.min((H * .94 - bw * sn) / c, bw * .72);
  if (bh < 60) { bh = Math.max(50, H * .7); bw = Math.min(W * .8, (W * .96 - bh * sn) / c); }
  cx = W / 2; cy = H * .5;
  h = Math.max(14, Math.min(22, Math.min(bw, bh) / 7.5));
  s = h * .46;
  rho0 = 0;
  for (let b = -6; b <= 6; b++) for (let a = -6; a <= 6; a++) {
    const x = (a + (b & 1) * .5) * s, y = b * s * .866, r = Math.hypot(x, y);
    if (r > 0 && r < h) rho0 += (1 - r / h) ** 2;
  }
  G = .05;
  fc = Math.ceil(bw / GS) + 1; fr = Math.ceil(bh / GS) + 1;
  F = new Float32Array(fc * fr);
  gcols = Math.ceil(bw / h) + 1; grows = Math.ceil(bh / h) + 1;
  ghead = new Int32Array(gcols * grows);
  fillTank(first ? .14 : 0);
  if (calm) settle(260);
  draw();
}
/* 300 ml of the 500: a hexagonal block 60% of the inner height, dropped from a little above its rest. */
function fillTank(lift) {
  const iw = bw - pad * 2, ih = bh - pad * 2;
  const cols = Math.floor(iw / s), rowsN = Math.round(ih * .6 / (s * .866));
  N = cols * rowsN;
  X = new Float32Array(N); Y = new Float32Array(N); PX = new Float32Array(N); PY = new Float32Array(N);
  VX = new Float32Array(N); VY = new Float32Array(N);
  NB = new Int32Array(N * MAXN); NC = new Uint8Array(N); gnext = new Int32Array(N);
  let i = 0;
  for (let r = 0; r < rowsN; r++) for (let q = 0; q < cols; q++) {
    X[i] = pad + (q + .5 + (r & 1) * .5) * s * (iw / (cols * s + s * .5)) + (Math.random() - .5) * .3;
    Y[i] = bh - pad - (r + .5) * s * .866 - ih * lift;
    i++;
  }
}

/* ── one simulation step (dt = 1 step = 1/120 s) ── */
function neighbours() {
  ghead.fill(-1);
  for (let i = 0; i < N; i++) {
    let c = (X[i] / h) | 0, r = (Y[i] / h) | 0;
    c = c < 0 ? 0 : c >= gcols ? gcols - 1 : c; r = r < 0 ? 0 : r >= grows ? grows - 1 : r;
    const k = r * gcols + c;
    gnext[i] = ghead[k]; ghead[k] = i;
  }
  const lim = (h * 1.15) ** 2;
  for (let i = 0; i < N; i++) {
    let n = 0;
    const c0 = (X[i] / h) | 0, r0 = (Y[i] / h) | 0, b = i * MAXN;
    for (let r = r0 - 1; r <= r0 + 1; r++) {
      if (r < 0 || r >= grows) continue;
      for (let c = c0 - 1; c <= c0 + 1; c++) {
        if (c < 0 || c >= gcols) continue;
        for (let j = ghead[r * gcols + c]; j !== -1; j = gnext[j]) {
          if (j === i || n >= MAXN) continue;
          const dx = X[j] - X[i], dy = Y[j] - Y[i];
          if (dx * dx + dy * dy < lim) NB[b + n++] = j;
        }
      }
    }
    NC[i] = n;
  }
}
function step(gx, gy) {
  const L = LIQ[liq];
  for (let i = 0; i < N; i++) { VX[i] += gx; VY[i] += gy; }
  if (stir) {
    const R = 30, R2 = R * R;
    for (let i = 0; i < N; i++) {
      const dx = X[i] - stir.x, dy = Y[i] - stir.y, d2 = dx * dx + dy * dy;
      if (d2 > R2) continue;
      const f = (1 - Math.sqrt(d2) / R) * .4;
      VX[i] += (stir.vx - VX[i]) * f; VY[i] += (stir.vy - VY[i]) * f;
    }
  }
  neighbours();
  /* viscosity: impulses on approaching pairs, each pair once */
  if (L.sigma || L.beta) {
    for (let i = 0; i < N; i++) {
      const b = i * MAXN;
      for (let q = 0; q < NC[i]; q++) {
        const j = NB[b + q];
        if (j < i) continue;
        const dx = X[j] - X[i], dy = Y[j] - Y[i], r = Math.sqrt(dx * dx + dy * dy);
        if (r >= h || r < 1e-5) continue;
        const ux = dx / r, uy = dy / r;
        const u = (VX[i] - VX[j]) * ux + (VY[i] - VY[j]) * uy;
        if (u <= 0) continue;
        let I = (1 - r / h) * (L.sigma * u + L.beta * u * u);
        if (I > u) I = u;
        I *= .5;
        VX[i] -= I * ux; VY[i] -= I * uy; VX[j] += I * ux; VY[j] += I * uy;
      }
    }
  }
  const vmax = s * .9;
  for (let i = 0; i < N; i++) {
    const v = Math.hypot(VX[i], VY[i]);
    if (v > vmax) { VX[i] *= vmax / v; VY[i] *= vmax / v; }
    PX[i] = X[i]; PY[i] = Y[i];
    X[i] += VX[i]; Y[i] += VY[i];
  }
  /* double-density relaxation */
  for (let i = 0; i < N; i++) {
    const b = i * MAXN;
    let rho = 0, near = 0;
    for (let q = 0; q < NC[i]; q++) {
      const j = NB[b + q], dx = X[j] - X[i], dy = Y[j] - Y[i], r2 = dx * dx + dy * dy;
      if (r2 >= h * h) continue;
      const a = 1 - Math.sqrt(r2) / h;
      rho += a * a; near += a * a * a;
    }
    const P = L.k * (rho - rho0), Pn = L.kn * near;
