.fxp-lorenz {
  /* Re-theme with these four. */
  --fxp-lorenz-paper: oklch(0.956 0.006 250);
  --fxp-lorenz-ink: oklch(0.27 0.02 260);
  --fxp-lorenz-left: oklch(0.58 0.19 32);
  --fxp-lorenz-right: oklch(0.47 0.08 195);

  --fxp-lorenz-muted: color-mix(in oklch, var(--fxp-lorenz-ink) 60%, var(--fxp-lorenz-paper));
  --fxp-lorenz-line: color-mix(in oklch, var(--fxp-lorenz-ink) 13%, transparent);
  --fxp-lorenz-chip: color-mix(in oklch, var(--fxp-lorenz-paper) 84%, transparent);
  --fxp-lorenz-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "panel panel";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 296px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxp-lorenz-paper);
  color: var(--fxp-lorenz-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxp-lorenz-line);

  & .fxp-lorenz__cv,
  & .fxp-lorenz__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxp-lorenz__cv { display: block; }
  & .fxp-lorenz__stage {
    z-index: 1;
    cursor: grab;
    touch-action: pan-y;
    outline: none;
    border-radius: inherit;
  }
  & .fxp-lorenz__stage:active { cursor: grabbing; }
  & .fxp-lorenz__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxp-lorenz-left), inset 0 0 0 5px color-mix(in oklch, var(--fxp-lorenz-left) 18%, transparent);
  }

