    margin: 0 0 3px;
    font: 500 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .04em;
    color: var(--fxp-lorenz-muted);
  }
  & .fxp-lorenz__title {
    margin: 0;
    font-family: ui-serif, Georgia, serif;
    font-size: clamp(20px, 6.6cqi, 29px);
    font-weight: 600;
    line-height: 1.02;
    letter-spacing: -0.015em;
    text-wrap: balance;
  }
  & .fxp-lorenz__read {
    grid-area: read;
    display: grid;
    gap: 6px;
    align-self: start;
    text-align: end;
  }
  & .fxp-lorenz__read div {
    display: grid;
    gap: 2px;
    transition: opacity .6s var(--fxp-lorenz-out) calc(var(--i) * 80ms + 150ms), translate .8s var(--fxp-lorenz-out) calc(var(--i) * 80ms + 150ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxp-lorenz__read dt {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxp-lorenz-muted);
  }
  & .fxp-lorenz__read dd {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 4px;
    margin: 0;
    font: 600 clamp(12px, 3.8cqi, 15px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
