/* Lorenz flow — dx/dt = σ(y − x), dy/dt = x(ρ − z) − y, dz/dt = xy − βz.
   A cloud of 2,400 starting points, Gaussian with σ = 0.001, is integrated with
   fourth-order Runge–Kutta. For the first few seconds it moves as one dot; then
   sensitive dependence stretches it into a filament and smears it over both
   wings — the Spread readout is the cloud's RMS radius. Every particle is inked
   by the wing it is on, so the switching between lobes stays visible. A long
   single trajectory is kept as a faint ghost so the attractor reads at rest. */
const cv = root.querySelector('.fxp-lorenz__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxp-lorenz__stage');
const probe = root.querySelector('.fxp-lorenz__probe');
const outSpread = root.querySelector('[data-k="spread"]');
const outL = root.querySelector('[data-k="left"]');
const outR = root.querySelector('[data-k="right"]');
const outRho = root.querySelector('[data-k="rho"]');
const outRegime = root.querySelector('[data-k="regime"]');
const outFixed = root.querySelector('[data-k="fixed"]');
const rhoIn = root.querySelector('.fxp-lorenz__rho input');
const panel = root.querySelector('.fxp-lorenz__panel');
const live = root.querySelector('.fxp-lorenz__sr');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const SIGMA = 10, BETA = 8 / 3, N = 2400, DT = .004, RATE = .85;   /* Lorenz time units per second */
const GHOST = 7000;
let rho = 28;
let W = 0, H = 0, DPR = 1;
const X = new Float64Array(N), Y = new Float64Array(N), Z = new Float64Array(N);
const SX = new Float32Array(N), SY = new Float32Array(N);
const gx = new Float32Array(GHOST), gy = new Float32Array(GHOST), gz = new Float32Array(GHOST);
const view = { yaw: -.6, base: -.6, pitch: .32 };
/* the attractor's extent: radius in the xy-plane and z-range, eased when ρ changes */
const ext = { r: 20, z0: 5, z1: 48 }, extT = { r: 20, z0: 5, z1: 48 };
let panelH = 70;
let idle = 0, drag = null, acc = 0, clock = 0, readT = 0, fresh = true;
let raf = 0, last = 0, seen = true, dead = false;
const pal = {};
const trail = document.createElement('canvas'), tx = trail.getContext('2d');
const grid = document.createElement('canvas');

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
const mix = (a, b, k) => [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * k);
function gauss() {
  let u = 0, v = 0;
  while (!u) u = Math.random();
  while (!v) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const BINS = 6;
function theme() {
  pal.paper = rgb('--fxp-lorenz-paper');
  pal.ink = rgb('--fxp-lorenz-ink');
  pal.left = rgb('--fxp-lorenz-left');
  pal.right = rgb('--fxp-lorenz-right');
  pal.bins = Array.from({ length: BINS }, (_, i) => mix(pal.left, pal.right, i / (BINS - 1)));
  paintGrid();
}
function paintGrid() {
  if (!W) return;
  grid.width = cv.width; grid.height = cv.height;
  const g = grid.getContext('2d');
  g.setTransform(DPR, 0, 0, DPR, 0, 0);
  const step = Math.max(14, Math.round(W / 24)), o = .5 / DPR;
  g.beginPath();
  for (let x = step; x < W; x += step) { g.moveTo(Math.round(x) + o, 0); g.lineTo(Math.round(x) + o, H); }
  for (let y = step; y < H; y += step) { g.moveTo(0, Math.round(y) + o); g.lineTo(W, Math.round(y) + o); }
  g.strokeStyle = css(pal.ink, .045);
  g.lineWidth = 1 / DPR;
  g.stroke();
}

/* ── dynamics ── */
let dx = 0, dy = 0, dz = 0;
function f(x, y, z) { dx = SIGMA * (y - x); dy = x * (rho - z) - y; dz = x * y - BETA * z; }
function rk4(i, h) {
  const x = X[i], y = Y[i], z = Z[i];
  f(x, y, z); const k1x = dx, k1y = dy, k1z = dz;
  f(x + k1x * h / 2, y + k1y * h / 2, z + k1z * h / 2); const k2x = dx, k2y = dy, k2z = dz;
  f(x + k2x * h / 2, y + k2y * h / 2, z + k2z * h / 2); const k3x = dx, k3y = dy, k3z = dz;
  f(x + k3x * h, y + k3y * h, z + k3z * h);
  X[i] = x + h / 6 * (k1x + 2 * k2x + 2 * k3x + dx);
  Y[i] = y + h / 6 * (k1y + 2 * k2y + 2 * k3y + dy);
  Z[i] = z + h / 6 * (k1z + 2 * k2z + 2 * k3z + dz);
}
/* One long orbit, after its transient, as the ghost of the attractor. */
function ghost() {
  let x = 1, y = 1, z = 1;
  const h = .006;
  for (let k = -1500; k < GHOST; k++) {
    f(x, y, z); const k1x = dx, k1y = dy, k1z = dz;
    f(x + k1x * h / 2, y + k1y * h / 2, z + k1z * h / 2); const k2x = dx, k2y = dy, k2z = dz;
    f(x + k2x * h / 2, y + k2y * h / 2, z + k2z * h / 2); const k3x = dx, k3y = dy, k3z = dz;
    f(x + k3x * h, y + k3y * h, z + k3z * h);
    x += h / 6 * (k1x + 2 * k2x + 2 * k3x + dx);
    y += h / 6 * (k1y + 2 * k2y + 2 * k3y + dy);
    z += h / 6 * (k1z + 2 * k2z + 2 * k3z + dz);
    if (k >= 0) { gx[k] = x; gy[k] = y; gz[k] = z; }
  }
  let r = 1, z0 = Infinity, z1 = -Infinity;
  for (let k = 0; k < GHOST; k++) {
    r = Math.max(r, Math.hypot(gx[k], gy[k]));
    z0 = Math.min(z0, gz[k]); z1 = Math.max(z1, gz[k]);
  }
  if (z1 - z0 < 2) { z0 -= 6; z1 += 6; r = Math.max(r, 6); }
  extT.r = r; extT.z0 = z0; extT.z1 = z1;
}
function release(announce) {
  const k = 2000 + ((Math.random() * (GHOST - 2001)) | 0);
  const x0 = gx[k] || 1, y0 = gy[k] || 1, z0 = gz[k] || 20;
  for (let i = 0; i < N; i++) {
    X[i] = x0 + gauss() * .001; Y[i] = y0 + gauss() * .001; Z[i] = z0 + gauss() * .001;
  }
  fresh = true;
  tx.setTransform(1, 0, 0, 1, 0, 0);
  tx.clearRect(0, 0, trail.width, trail.height);
  if (announce) live.textContent = 'A fresh cloud of 2,400 starting points, a thousandth apart.';
}
function spread() {
  let mx = 0, my = 0, mz = 0;
  for (let i = 0; i < N; i++) { mx += X[i]; my += Y[i]; mz += Z[i]; }
  mx /= N; my /= N; mz /= N;
  let s = 0, left = 0;
  for (let i = 0; i < N; i++) {
    s += (X[i] - mx) ** 2 + (Y[i] - my) ** 2 + (Z[i] - mz) ** 2;
    if (X[i] < 0) left++;
