}
function readout() {
  const [s, left] = spread();
  outSpread.textContent = s < 1 ? s.toPrecision(2) : s.toFixed(1);
  const l = Math.round(left / N * 100);
  outL.textContent = l; outR.textContent = 100 - l;
}
function regime() {
  outRho.textContent = rho.toFixed(1);
  let r;
  if (rho < 1) r = 'Origin stable: convection dies';
  else if (rho < 13.926) r = 'Steady rolls: spirals into C±';
  else if (rho < 24.06) r = 'Transient chaos, then C±';
  else if (rho < 24.74) r = 'Bistable: chaos and stable C±';
  else r = 'Chaotic: the butterfly';
  outRegime.textContent = r;
  if (rho > 1) {
    const c = Math.sqrt(BETA * (rho - 1));
    outFixed.textContent = 'C± (±' + c.toFixed(2) + ', ±' + c.toFixed(2) + ', ' + (rho - 1).toFixed(1) + ')';
  } else outFixed.textContent = 'C± do not exist';
}

/* ── projection ── */
let cy0 = 1, sy0 = 0, cp = 1, sp = 1, K = 1, ox = 0, oy = 0;
let PX = 0, PY = 0;
/* Fit the attractor between the heading and the panel, whatever ρ and the view. */
let zc = 27;
function camera() {
  cy0 = Math.cos(view.yaw); sy0 = Math.sin(view.yaw);
  cp = Math.cos(view.pitch); sp = Math.sin(view.pitch);
  const top = 34, bottom = H - panelH - 10;
  const tall = (ext.z1 - ext.z0) * Math.abs(cp) + ext.r * 2 * Math.abs(sp);
  K = Math.min(W * .9 / (ext.r * 2), (bottom - top) / Math.max(1, tall));
  zc = (ext.z0 + ext.z1) / 2;
