}
function project(x, y, z) {
  const a = x * cy0 - y * sy0, d = x * sy0 + y * cy0, zz = z - zc;
  PX = ox + a * K;
  PY = oy - (zz * cp - d * sp) * K;
}

function draw(fade, dt) {
  camera();
  /* trails: new motion is inked on a layer that slowly gives it back to the paper */
  tx.setTransform(1, 0, 0, 1, 0, 0);
