    tx.globalCompositeOperation = 'destination-out';
    tx.fillStyle = 'rgba(0,0,0,' + (1 - Math.exp(-dt * (drag ? 9 : 3.2))).toFixed(4) + ')';
    tx.fillRect(0, 0, trail.width, trail.height);
