  for (let i = 0; i < N; i++) {
    project(X[i], Y[i], Z[i]);
    const b = Math.max(0, Math.min(BINS - 1, Math.round((Math.tanh(X[i] / 3) + 1) / 2 * (BINS - 1))));
    const p = paths[b];
    if (fresh || calm) { p.rect(PX - .8, PY - .8, 1.6, 1.6); }
