    if (k === 0) ctx.moveTo(PX, PY); else ctx.lineTo(PX, PY);
  }
  ctx.strokeStyle = css(pal.ink, calm ? .3 : .13);
  ctx.lineWidth = calm ? .7 : .6;
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.drawImage(trail, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
