    const a = x * cy0 - y * sy0, d = x * sy0 + y * cy0;
    const ex = gxo + a * 12, ey = gyo - (z * cp - d * sp) * 12;
    ctx.strokeStyle = css(pal.ink, .4);
    ctx.beginPath(); ctx.moveTo(gxo, gyo); ctx.lineTo(ex, ey); ctx.stroke();
    ctx.fillStyle = css(pal.ink, .55);
    ctx.fillText(l, ex + (ex - gxo) * .35 - 2, ey + (ey - gyo) * .35);
  });
}

/* ── host ── */
function size(w, h) {
  if (w < 2 || h < 2) return;
  const first = !W;
