function advance(t, h = DT) { const n = Math.round(t / h); for (let s = 0; s < n; s++) for (let i = 0; i < N; i++) rk4(i, h); }
/* Reduced motion: the cloud is carried far enough to fill the attractor, then drawn once as a still. */
